(321684,35743,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué comida tan ligera, obvio. Ellos ... comer todo lo que hay en esta mesa.'::text,'van a'::text,NULL::text,'están'::text,'Qué comida tan ligera, obvio. Ellos van a comer todo lo que hay en esta mesa.'::text),
(321683,35743,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un déjeuner si léger, évidemment. Ils ... manger tout ce qu''il y a sur cette table.'::text,'vont'::text,NULL::text,'sont'::text,'Un déjeuner si léger, évidemment. Ils vont manger tout ce qu''il y a sur cette table.'::text),
