(322871,35875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super visée, évidemment. Hier, elle ... le ballon dans la mer.'::text,'a lancé'::text,'lance'::text,NULL::text,'Super visée, évidemment. Hier, elle a lancé le ballon dans la mer.'::text),
(322874,35875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika nişan, tabii. Dün o topu denize ...'::text,'attı'::text,'atar'::text,NULL::text,'Harika nişan, tabii. Dün o topu denize attı.'::text),
(322875,35875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek célzás, persze. Tegnap ő a tengerbe ... a labdát.'::text,'dobta'::text,'dobja'::text,NULL::text,'Remek célzás, persze. Tegnap ő a tengerbe dobta a labdát.'::text),
(305949,33995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... ein ganzes Auto, Respekt.'::text,'bewegt'::text,'bewegen'::text,'bewegend'::text,'Alter, er bewegt ein ganzes Auto, Respekt.'::text),
(305953,33995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... цілу машину, респект.'::text,'рухає'::text,'рухати'::text,'рухаючи'::text,'Бро, він рухає цілу машину, респект.'::text),
(305952,33995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... un coche entero, hay que respetarlo.'::text,'mueve'::text,'mover'::text,'moviendo'::text,'Tío, él mueve un coche entero, hay que respetarlo.'::text),
(305951,33995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... une voiture entière, respect.'::text,'déplace'::text,'déplacer'::text,'déplaçant'::text,'Mec, il déplace une voiture entière, respect.'::text),
(305954,33995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o koca bir arabayı ..., saygı duymak lazım.'::text,'hareket ettirir'::text,'hareket ettirmek'::text,'hareket ettirerek'::text,'Kanka, o koca bir arabayı hareket ettirir, saygı duymak lazım.'::text),
(305955,33995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő egy egész autót ..., ezt tisztelni kell.'::text,'mozgat'::text,'mozgatni'::text,'mozgató'::text,'Tesó, ő egy egész autót mozgat, ezt tisztelni kell.'::text),
(306012,34002,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellos: Das Auto sprang nicht an, ... hat er es mit den Händen bewegt.'::text,'also'::text,'aber'::text,'weil'::text,'Makellos: Das Auto sprang nicht an, also hat er es mit den Händen bewegt.'::text),
(306016,34002,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганно: машина не завелася, ... він пересунув її руками.'::text,'тому'::text,'але'::text,'бо'::text,'Бездоганно: машина не завелася, тому він пересунув її руками.'::text),
(306015,34002,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impecable: el coche no arrancó, ... él lo movió con las manos.'::text,'así que'::text,'pero'::text,'porque'::text,'Impecable: el coche no arrancó, así que él lo movió con las manos.'::text),
(306014,34002,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impeccable : la voiture n''a pas démarré, ... il l''a déplacée à la main.'::text,'donc'::text,'mais'::text,'parce que'::text,'Impeccable : la voiture n''a pas démarré, donc il l''a déplacée à la main.'::text),
(306017,34002,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz: araba çalışmadı, ... o arabayı elleriyle hareket ettirdi.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Kusursuz: araba çalışmadı, bu yüzden o arabayı elleriyle hareket ettirdi.'::text),
(306018,34002,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan: az autó nem indult, ... ő a kezével tolta el.'::text,'ezért'::text,'de'::text,'mert'::text,'Hibátlan: az autó nem indult, ezért ő a kezével tolta el.'::text),
(299730,33304,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann arbeitet sonst an seinem Schreibtisch, aber jetzt ... er sich darunter.'::text,'versteckt'::text,'versteckt'::text,NULL::text,'Der Mann arbeitet sonst an seinem Schreibtisch, aber jetzt versteckt er sich darunter.'::text),
(299734,33304,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік зазвичай працює за своїм столом, але зараз він ... під ним.'::text,'ховається'::text,'ховається'::text,NULL::text,'Чоловік зазвичай працює за своїм столом, але зараз він ховається під ним.'::text),
(299733,33304,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre normalmente trabaja en su mesa, pero ahora él ... debajo de ella.'::text,'se está escondiendo'::text,'se esconde'::text,NULL::text,'El hombre normalmente trabaja en su mesa, pero ahora él se está escondiendo debajo de ella.'::text),
(299732,33304,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme travaille d''habitude à son bureau, mais là, il ... dessous.'::text,'est en train de se cacher'::text,'se cache'::text,NULL::text,'L''homme travaille d''habitude à son bureau, mais là, il est en train de se cacher dessous.'::text),
(299735,33304,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam genelde masasında çalışır ama şimdi o masanın altında ...'::text,'saklanıyor'::text,'saklanır'::text,NULL::text,'Adam genelde masasında çalışır ama şimdi o masanın altında saklanıyor.'::text),
(299736,33304,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi általában az íróasztalánál dolgozik, de most ő ... alatta.'::text,'rejtőzik'::text,'rejtőzik'::text,NULL::text,'A férfi általában az íróasztalánál dolgozik, de most ő rejtőzik alatta.'::text),
(301953,33551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'To-do: einen Schlüssel finden. Nach 40 Minuten ist ... Schlüssel in ihrer Hand.'::text,'der'::text,'ein'::text,'ein'::text,'To-do: einen Schlüssel finden. Nach 40 Minuten ist der Schlüssel in ihrer Hand.'::text),
(301957,33551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завдання: знайти ключ. Через 40 хвилин ... ключ у неї в руці.'::text,''::text,NULL::text,NULL::text,'Завдання: знайти ключ. Через 40 хвилин ключ у неї в руці.'::text),
(301956,33551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tarea pendiente: encontrar una llave. Después de 40 minutos, ... llave está en su mano.'::text,'la'::text,'una'::text,'una'::text,'Tarea pendiente: encontrar una llave. Después de 40 minutos, la llave está en su mano.'::text),
(301955,33551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Action à mener : trouver une clé. Au bout de 40 minutes, ... clé est dans sa main.'::text,'la'::text,'une'::text,'une'::text,'Action à mener : trouver une clé. Au bout de 40 minutes, la clé est dans sa main.'::text),
(301958,33551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yapılacak iş: bir anahtar bulmak. 40 dakika sonra ... anahtar onun elinde.'::text,''::text,'bir'::text,'bir'::text,'Yapılacak iş: bir anahtar bulmak. 40 dakika sonra anahtar onun elinde.'::text),
(301959,33551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teendő: kulcsot találni. 40 perc után ... kulcs a kezében van.'::text,'a'::text,'egy'::text,'egy'::text,'Teendő: kulcsot találni. 40 perc után a kulcs a kezében van.'::text),
(301989,33555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du verschwendest nicht ... Zeit. Du findest den Schlüssel.'::text,'viel'::text,'viele'::text,'etwas'::text,'Ehrlich gesagt, du verschwendest nicht viel Zeit. Du findest den Schlüssel.'::text),
(301993,33555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти не гаєш ... часу. Ти знаходиш ключ.'::text,'багато'::text,'багато'::text,'трохи'::text,'Не буду брехати, ти не гаєш багато часу. Ти знаходиш ключ.'::text),
(301992,33555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, tú no pierdes ... tiempo. Encuentras la llave.'::text,'mucho'::text,'muchos'::text,'algo de'::text,'No te voy a mentir, tú no pierdes mucho tiempo. Encuentras la llave.'::text),
(301991,33555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ne perds pas ... temps. Tu trouves la clé.'::text,'beaucoup de'::text,'beaucoup de'::text,'du'::text,'Je vais pas mentir, tu ne perds pas beaucoup de temps. Tu trouves la clé.'::text),
(301994,33555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen ... zaman kaybetmiyorsun. Anahtarı buluyorsun.'::text,'çok'::text,'çok'::text,'biraz'::text,'Yalan yok, sen çok zaman kaybetmiyorsun. Anahtarı buluyorsun.'::text),
(301995,33555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te nem vesztegetsz ... időt. Megtalálod a kulcsot.'::text,'sok'::text,'sok'::text,'némi'::text,'Nem hazudok, te nem vesztegetsz sok időt. Megtalálod a kulcsot.'::text),
(328206,36468,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er hat einen Schraubenschlüssel, er ... am Motor arbeiten, echt.'::text,'wird'::text,'wird'::text,'ist'::text,'Yo, er hat einen Schraubenschlüssel, er wird am Motor arbeiten, echt.'::text),
(328210,36468,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, у нього є гайковий ключ, він ... працювати над двигуном, чесно.'::text,'збирається'::text,'буде'::text,'є'::text,'Йо, у нього є гайковий ключ, він збирається працювати над двигуном, чесно.'::text),
(328209,36468,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, tiene una llave inglesa, él ... trabajar en el motor, en serio.'::text,'va a'::text,NULL::text,'está'::text,'Oye, tiene una llave inglesa, él va a trabajar en el motor, en serio.'::text),
(328208,36468,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, il a une clé plate, il ... travailler sur le moteur, sérieux.'::text,'va'::text,NULL::text,'est'::text,'Yo, il a une clé plate, il va travailler sur le moteur, sérieux.'::text),
(328211,36468,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onda bir İngiliz anahtarı var, o motor üzerinde ..., cidden.'::text,'çalışacak'::text,'çalışacak'::text,NULL::text,'Kanka, onda bir İngiliz anahtarı var, o motor üzerinde çalışacak, cidden.'::text),
(328212,36468,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, van egy csavarkulcsa, ő a motoron ... dolgozni, komolyan.'::text,'fog'::text,'fog'::text,'van'::text,'Figyu, van egy csavarkulcsa, ő a motoron fog dolgozni, komolyan.'::text),
(320421,35603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gruppe schaut zu ... hohen Holzkonstruktion hoch.'::text,'dieser'::text,'diesen'::text,'jenen'::text,'Die Gruppe schaut zu dieser hohen Holzkonstruktion hoch.'::text),
(320425,35603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Група дивиться вгору на ... високу дерев''яну конструкцію.'::text,'цю'::text,'ці'::text,'ті'::text,'Група дивиться вгору на цю високу дерев''яну конструкцію.'::text),
(320424,35603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El grupo mira hacia arriba a ... alta estructura de madera.'::text,'esta'::text,'estas'::text,'esas'::text,'El grupo mira hacia arriba a esta alta estructura de madera.'::text),
(320423,35603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe lève les yeux vers ... haute structure en bois.'::text,'cette'::text,'ces'::text,'ces'::text,'Le groupe lève les yeux vers cette haute structure en bois.'::text),
(320426,35603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup ... yüksek ahşap yapıya bakıyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Grup bu yüksek ahşap yapıya bakıyor.'::text),
(320427,35603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csoport felnéz ... a magas faszerkezetre.'::text,'erre'::text,'ezekre'::text,'azokra'::text,'A csoport felnéz erre a magas faszerkezetre.'::text),
(320439,35605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie brauchen so viel ... für die Konstruktion.'::text,'Holz'::text,'Holz'::text,'Bretter'::text,'Sie brauchen so viel Holz für die Konstruktion.'::text),
(320443,35605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони потребують стільки ... для конструкції.'::text,'деревини'::text,'деревини'::text,'дощок'::text,'Вони потребують стільки деревини для конструкції.'::text),
(320442,35605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos necesitan tanta ... para la estructura.'::text,'madera'::text,'madera'::text,'tablas'::text,'Ellos necesitan tanta madera para la estructura.'::text),
(320441,35605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont besoin de tellement de ... pour la structure.'::text,'bois'::text,'bois'::text,'planches'::text,'Ils ont besoin de tellement de bois pour la structure.'::text),
(320444,35605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar yapı için o kadar çok ... ihtiyaç duyuyor.'::text,'ahşaba'::text,'ahşaplara'::text,'tahtalara'::text,'Onlar yapı için o kadar çok ahşaba ihtiyaç duyuyor.'::text),
(320445,35605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nekik annyi ... kell a szerkezethez.'::text,'fa'::text,'fa'::text,'deszka'::text,'Nekik annyi fa kell a szerkezethez.'::text),
(298452,33162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Der Kürbis ... jetzt nur noch zwei Hälften, für immer!'::text,'hat'::text,'haben'::text,'ist'::text,'Nein! Der Kürbis hat jetzt nur noch zwei Hälften, für immer!'::text),
(298456,33162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Гарбуз тепер ... лише дві половинки, назавжди!'::text,'має'::text,'мати'::text,'є'::text,'Ні! Гарбуз тепер має лише дві половинки, назавжди!'::text),
(298455,33162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡La calabaza ahora ... solo dos mitades, para siempre!'::text,'tiene'::text,'tienen'::text,'está'::text,'¡No! ¡La calabaza ahora tiene solo dos mitades, para siempre!'::text),
(298454,33162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! La citrouille ... seulement deux moitiés maintenant, pour toujours !'::text,'a'::text,'ont'::text,'est'::text,'Non ! La citrouille a seulement deux moitiés maintenant, pour toujours !'::text),
(298457,33162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Balkabağının artık sadece iki yarısı ..., sonsuza dek!'::text,'var'::text,'var'::text,NULL::text,'Hayır! Balkabağının artık sadece iki yarısı var, sonsuza dek!'::text),
(298458,33162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! A töknek most már csak két fele ..., örökre!'::text,'van'::text,'van'::text,'van'::text,'Ne! A töknek most már csak két fele van, örökre!'::text),
(298515,33169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Da ... zwei Hälften eines riesigen Kürbisses auf dem Gras!'::text,'sind'::text,'ist'::text,'sein'::text,'Albtraum! Da sind zwei Hälften eines riesigen Kürbisses auf dem Gras!'::text),
(298519,33169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! На траві ... дві половинки величезного гарбуза!'::text,'є'::text,'є'::text,'бути'::text,'Жах! На траві є дві половинки величезного гарбуза!'::text),
(298518,33169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡... dos mitades de una calabaza gigante en el césped!'::text,'Hay'::text,'Hay'::text,'Hay'::text,'¡Pesadilla! ¡Hay dos mitades de una calabaza gigante en el césped!'::text),
(298517,33169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! ... deux moitiés d''une citrouille géante sur l''herbe !'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Cauchemar ! Il y a deux moitiés d''une citrouille géante sur l''herbe !'::text),
(298520,33169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Çimenlerin üstünde dev bir balkabağının iki yarısı ...!'::text,'var'::text,'var'::text,'olmak'::text,'Kâbus! Çimenlerin üstünde dev bir balkabağının iki yarısı var!'::text),
(298521,33169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Egy óriástök két fele ... a füvön!'::text,'van'::text,'van'::text,'lenni'::text,'Rémálom! Egy óriástök két fele van a füvön!'::text),
(294771,32753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sitzt sie am Ende? Auf dem Boden.'::text,'Wo'::text,'Was'::text,'Wer'::text,'Wo sitzt sie am Ende? Auf dem Boden.'::text),
(294775,32753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона сидить наприкінці? На підлозі.'::text,'Де'::text,'Що'::text,'Хто'::text,'Де вона сидить наприкінці? На підлозі.'::text),
(294774,32753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... se sienta ella al final? En el suelo.'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'¿Dónde se sienta ella al final? En el suelo.'::text),
(294773,32753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est-ce qu''elle s''assoit à la fin ? Par terre.'::text,'Où'::text,'Que'::text,'Qui'::text,'Où est-ce qu''elle s''assoit à la fin ? Par terre.'::text),
(294776,32753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sonunda ... oturuyor? Yerde.'::text,'nerede'::text,'ne'::text,'kim'::text,'O sonunda nerede oturuyor? Yerde.'::text),
(294777,32753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ül ő a végén? A padlón.'::text,'Hol'::text,'Mi'::text,'Ki'::text,'Hol ül ő a végén? A padlón.'::text),
(294807,32757,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du wischst sonst kleine Küchen, aber gestern ... du den Boden einer Lagerhalle. Ikonisch.'::text,'wischtest'::text,'wischst'::text,NULL::text,'Du wischst sonst kleine Küchen, aber gestern wischtest du den Boden einer Lagerhalle. Ikonisch.'::text),
(294811,32757,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зазвичай миєш шваброю маленькі кухні, а вчора ти ... підлогу складу. Легенда.'::text,'помив'::text,'миєш'::text,NULL::text,'Ти зазвичай миєш шваброю маленькі кухні, а вчора ти помив підлогу складу. Легенда.'::text),
(294810,32757,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú normalmente friegas cocinas pequeñas, pero ayer ... el suelo de un almacén. Icónico.'::text,'fregaste'::text,'friegas'::text,NULL::text,'Tú normalmente friegas cocinas pequeñas, pero ayer fregaste el suelo de un almacén. Icónico.'::text),
(294809,32757,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, tu passes la serpillière dans de petites cuisines, mais hier tu ... le sol d''un entrepôt. Iconique.'::text,'as passé la serpillière sur'::text,'passes la serpillière sur'::text,NULL::text,'D''habitude, tu passes la serpillière dans de petites cuisines, mais hier tu as passé la serpillière sur le sol d''un entrepôt. Iconique.'::text),
(294812,32757,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen genelde küçük mutfakları paspaslarsın ama dün bir deponun zeminini ... Efsane.'::text,'paspasladın'::text,'paspaslarsın'::text,NULL::text,'Sen genelde küçük mutfakları paspaslarsın ama dün bir deponun zeminini paspasladın Efsane.'::text),
(294813,32757,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te általában kis konyhákat mosol fel, de tegnap egy raktár padlóját ... Ikonikus.'::text,'mostad fel'::text,'mosod fel'::text,NULL::text,'Te általában kis konyhákat mosol fel, de tegnap egy raktár padlóját mostad fel Ikonikus.'::text),
(297858,33096,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat gesagt, du ... die Blumen täglich gießen, damit sie wachsen.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Bestie, sie hat gesagt, du solltest die Blumen täglich gießen, damit sie wachsen.'::text),
(297862,33096,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, вона сказала, що ти ... поливати квіти щодня, щоб вони росли.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Подружко, вона сказала, що ти мала б поливати квіти щодня, щоб вони росли.'::text),
(297861,33096,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, ella dijo que tú ... regar las flores a diario para que crezcan.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Amiga, ella dijo que tú deberías regar las flores a diario para que crezcan.'::text),
(297860,33096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle a dit que tu ... arroser les fleurs tous les jours pour qu''elles poussent.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Ma belle, elle a dit que tu devrais arroser les fleurs tous les jours pour qu''elles poussent.'::text),
(297863,33096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o dedi ki çiçekler büyüsün diye sen onları her gün ...'::text,'sulamalısın'::text,'sulamalısın'::text,'sulamalısın'::text,'Kanka, o dedi ki çiçekler büyüsün diye sen onları her gün sulamalısın.'::text),
(297864,33096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta, hogy naponta ... meglocsolnod a virágokat, hogy nőjenek.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Csajszi, ő azt mondta, hogy naponta kellene meglocsolnod a virágokat, hogy nőjenek.'::text),
(320754,35640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Sommer laufen ... Kinder durch den Rasensprenger.'::text,'zwei'::text,'zweite'::text,'Zweien'::text,'Im Sommer laufen zwei Kinder durch den Rasensprenger.'::text),
(320758,35640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Улітку ... дітей бігають крізь дощувач.'::text,'двоє'::text,'другі'::text,'двійки'::text,'Улітку двоє дітей бігають крізь дощувач.'::text),
(320757,35640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En verano, ... niños corren bajo el aspersor.'::text,'dos'::text,'segundos'::text,'dos'::text,'En verano, dos niños corren bajo el aspersor.'::text),
(320756,35640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En été, ... enfants courent sous l''arroseur.'::text,'deux'::text,'deuxièmes'::text,'deux'::text,'En été, deux enfants courent sous l''arroseur.'::text),
(320759,35640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yazın ... çocuk fıskiyenin içinden koşuyor.'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'Yazın iki çocuk fıskiyenin içinden koşuyor.'::text),
(320760,35640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyáron ... gyerek szalad át a locsolón.'::text,'két'::text,'második'::text,'kettesek'::text,'Nyáron két gyerek szalad át a locsolón.'::text),
(320772,35642,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein trockener Sommer, klar. Da ist ... Wasser auf dem ganzen Rasen.'::text,'eine Menge'::text,'viele'::text,'ein paar'::text,'Ein trockener Sommer, klar. Da ist eine Menge Wasser auf dem ganzen Rasen.'::text),
(320776,35642,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сухе літо, звісно. По всьому газону ... води.'::text,'багато'::text,'багато'::text,'кілька'::text,'Сухе літо, звісно. По всьому газону багато води.'::text),
(320775,35642,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un verano seco, claro. Hay ... agua por todo el césped.'::text,'un montón de'::text,'muchas'::text,'unas pocas'::text,'Un verano seco, claro. Hay un montón de agua por todo el césped.'::text),
(320774,35642,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un été sec, évidemment. Il y a ... eau sur toute la pelouse.'::text,'plein d'''::text,'beaucoup d'''::text,'quelques'::text,'Un été sec, évidemment. Il y a plein d'' eau sur toute la pelouse.'::text),
(320777,35642,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurak bir yaz, tabii. Bütün çimenlerde ... su var.'::text,'çok'::text,'çok'::text,'birkaç'::text,'Kurak bir yaz, tabii. Bütün çimenlerde çok su var.'::text),
(320778,35642,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Száraz nyár, persze. Az egész gyepen ... víz van.'::text,'rengeteg'::text,'sok'::text,'pár'::text,'Száraz nyár, persze. Az egész gyepen rengeteg víz van.'::text),
(318135,35349,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... löst er das Problem? Auf der ganzen Tafel! Völlig verrückt!'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Wo löst er das Problem? Auf der ganzen Tafel! Völlig verrückt!'::text),
(318139,35349,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він розв''язує задачу? На всій дошці! Повне божевілля!'::text,'Де'::text,'Коли'::text,'Хто'::text,'Де він розв''язує задачу? На всій дошці! Повне божевілля!'::text),
(318138,35349,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... resuelve él el problema? ¡En toda la pizarra! ¡Una locura total!'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde resuelve él el problema? ¡En toda la pizarra! ¡Una locura total!'::text),
(318137,35349,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est-ce qu''il résout le problème ? Sur tout le tableau ! Complètement fou !'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où est-ce qu''il résout le problème ? Sur tout le tableau ! Complètement fou !'::text),
(318140,35349,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O problemi ... çözüyor? Bütün tahtada! Resmen çılgınlık!'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'O problemi nerede çözüyor? Bütün tahtada! Resmen çılgınlık!'::text),
(318141,35349,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... oldja meg ő a feladatot? Az egész táblán! Teljes őrület!'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol oldja meg ő a feladatot? Az egész táblán! Teljes őrület!'::text),
(318171,35353,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... gerade das größte Problem aller Zeiten, ohne Witz.'::text,'löst'::text,'löst'::text,NULL::text,'Alter, er löst gerade das größte Problem aller Zeiten, ohne Witz.'::text),
(318175,35353,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він саме зараз ... найбільшу задачу в історії, чесно.'::text,'розв''язує'::text,'розв''язує'::text,NULL::text,'Бро, він саме зараз розв''язує найбільшу задачу в історії, чесно.'::text),
(318174,35353,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... el mayor problema de la historia ahora mismo, sin mentir.'::text,'está resolviendo'::text,'resuelve'::text,NULL::text,'Tío, él está resolviendo el mayor problema de la historia ahora mismo, sin mentir.'::text),
(318173,35353,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... le plus gros problème de tous les temps en ce moment, sans mentir.'::text,'est en train de résoudre'::text,'résout'::text,NULL::text,'Mec, il est en train de résoudre le plus gros problème de tous les temps en ce moment, sans mentir.'::text),
(318176,35353,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o şu an gelmiş geçmiş en büyük problemi ..., cidden.'::text,'çözüyor'::text,'çözer'::text,NULL::text,'Kanka, o şu an gelmiş geçmiş en büyük problemi çözüyor, cidden.'::text),
(318177,35353,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő most épp minden idők legnagyobb feladatát ..., komolyan.'::text,'oldja meg'::text,'oldja meg'::text,NULL::text,'Tesó, ő most épp minden idők legnagyobb feladatát oldja meg, komolyan.'::text),
(312384,34710,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... dir jedes Wort auf diesen Karten. Ehrlich, so cool.'::text,'merkst'::text,'merkt'::text,'merkend'::text,'Du merkst dir jedes Wort auf diesen Karten. Ehrlich, so cool.'::text),
(312388,34710,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... кожне слово на цих картках. Чесно, так круто.'::text,'пам''ятаєш'::text,'пам''ятає'::text,'пам''ятаючи'::text,'Ти пам''ятаєш кожне слово на цих картках. Чесно, так круто.'::text),
(312387,34710,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... todas las palabras de estas tarjetas. En serio, qué guay.'::text,'recuerdas'::text,'recuerda'::text,'recordando'::text,'Tú recuerdas todas las palabras de estas tarjetas. En serio, qué guay.'::text),
(312386,34710,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... chaque mot sur ces cartes. Franchement, trop cool.'::text,'retiens'::text,'retient'::text,'retenant'::text,'Tu retiens chaque mot sur ces cartes. Franchement, trop cool.'::text),
(312389,34710,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen bu kartlardaki her kelimeyi ... Açıkçası, çok havalı.'::text,'hatırlarsın'::text,'hatırlar'::text,'hatırlayarak'::text,'Sen bu kartlardaki her kelimeyi hatırlarsın Açıkçası, çok havalı.'::text),
(312390,34710,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... minden szóra ezeken a kártyákon. Őszintén, nagyon menő.'::text,'emlékszel'::text,'emlékszik'::text,'emlékező'::text,'Te emlékszel minden szóra ezeken a kártyákon. Őszintén, nagyon menő.'::text),
(312420,34714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziel: 200 Wörter. Meistens vergisst er sie, aber gestern ... er sie alle.'::text,'behielt'::text,'behält'::text,NULL::text,'Ziel: 200 Wörter. Meistens vergisst er sie, aber gestern behielt er sie alle.'::text),
(312424,34714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль: 200 слів. Зазвичай він забуває, але вчора ... їх усі.'::text,'запам''ятав'::text,'запам''ятовує'::text,NULL::text,'Ціль: 200 слів. Зазвичай він забуває, але вчора запам''ятав їх усі.'::text),
(312423,34714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo: 200 palabras. Normalmente él se olvida, pero ayer las ... todas.'::text,'recordó'::text,'recuerda'::text,NULL::text,'Objetivo: 200 palabras. Normalmente él se olvida, pero ayer las recordó todas.'::text),
(312422,34714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif : 200 mots. D''habitude il oublie, mais hier il les ... tous.'::text,'a retenus'::text,'retient'::text,NULL::text,'Objectif : 200 mots. D''habitude il oublie, mais hier il les a retenus tous.'::text),
(312425,34714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedef: 200 kelime. O genelde unutur ama dün hepsini ...'::text,'hatırladı'::text,'hatırlar'::text,NULL::text,'Hedef: 200 kelime. O genelde unutur ama dün hepsini hatırladı.'::text),
(312426,34714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cél: 200 szó. Ő általában felejt, de tegnap mindegyikre ...'::text,'emlékezett'::text,'emlékszik'::text,NULL::text,'Cél: 200 szó. Ő általában felejt, de tegnap mindegyikre emlékezett.'::text),
(322221,35803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Lehrerin hält ... Stift, also ist er in ihrer Hand.'::text,'ihren'::text,'seinen'::text,'ihren'::text,'Die Lehrerin hält ihren Stift, also ist er in ihrer Hand.'::text),
(322225,35803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вчителька тримає ... ручку, тож вона в її руці.'::text,'свою'::text,'свою'::text,'свою'::text,'Вчителька тримає свою ручку, тож вона в її руці.'::text),
(322224,35803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La profesora sostiene ... bolígrafo, así que está en su mano.'::text,'su'::text,'su'::text,'su'::text,'La profesora sostiene su bolígrafo, así que está en su mano.'::text),
(322223,35803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La prof tient ... stylo, donc il est dans sa main.'::text,'son'::text,'son'::text,'leur'::text,'La prof tient son stylo, donc il est dans sa main.'::text),
(322226,35803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğretmen ... kalemini tutuyor, yani kalem onun elinde.'::text,'onun'::text,'onun'::text,'onların'::text,'Öğretmen onun kalemini tutuyor, yani kalem onun elinde.'::text),
(322227,35803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tanárnő fogja a ..., tehát a kezében van.'::text,'tollát'::text,'tollát'::text,'tollukat'::text,'A tanárnő fogja a tollát, tehát a kezében van.'::text),
(322248,35806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, Frau Lehrerin, du hast so viel ... und machst trotzdem weiter.'::text,'Arbeit'::text,'Arbeit'::text,'eine Arbeit'::text,'Ehrlich, Frau Lehrerin, du hast so viel Arbeit und machst trotzdem weiter.'::text),
(322252,35806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, вчителько, ти маєш стільки ... і все одно не зупиняєшся.'::text,'роботи'::text,'роботи'::text,'роботи'::text,'Чесно, вчителько, ти маєш стільки роботи і все одно не зупиняєшся.'::text),
(322251,35806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, profe, tú tienes tanto ... y sigues adelante.'::text,'trabajo'::text,'trabajo'::text,'un trabajo'::text,'En serio, profe, tú tienes tanto trabajo y sigues adelante.'::text),
(322250,35806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, la prof, tu as tellement de ... et tu continues.'::text,'travail'::text,'travail'::text,'un travail'::text,'Franchement, la prof, tu as tellement de travail et tu continues.'::text),
(322253,35806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası hocam, senin o kadar çok ... var ve sen hâlâ devam ediyorsun.'::text,'işin'::text,'işin'::text,'bir işin'::text,'Açıkçası hocam, senin o kadar çok işin var ve sen hâlâ devam ediyorsun.'::text),
(322254,35806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, tanárnő, neked annyi ... van, és te mégis folytatod.'::text,'munkád'::text,'munkád'::text,'egy munkád'::text,'Őszintén, tanárnő, neked annyi munkád van, és te mégis folytatod.'::text),
(328278,36476,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist ... beste Arbeiter in diesem Lager.'::text,'der'::text,'ein'::text,'ein'::text,'Ehrlich, du bist der beste Arbeiter in diesem Lager.'::text),
(328282,36476,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... найкращий працівник на цьому складі.'::text,''::text,NULL::text,NULL::text,'Чесно, ти найкращий працівник на цьому складі.'::text),
(328281,36476,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, tú eres ... mejor trabajador de este almacén.'::text,'el'::text,'un'::text,'un'::text,'En serio, tú eres el mejor trabajador de este almacén.'::text),
(328280,36476,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu es ... meilleur employé de cet entrepôt.'::text,'le'::text,'un'::text,'un'::text,'Franchement, tu es le meilleur employé de cet entrepôt.'::text),
(328283,36476,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen bu depodaki ... en iyi işçisin.'::text,''::text,'bir'::text,'bir'::text,'Açıkçası sen bu depodaki en iyi işçisin.'::text),
(328284,36476,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te vagy ... legjobb dolgozó ebben a raktárban.'::text,'a'::text,'egy'::text,'egy'::text,'Őszintén, te vagy a legjobb dolgozó ebben a raktárban.'::text),
(328323,36481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... heute viele Kisten um den Arbeiter herum.'::text,'sind'::text,'ist'::text,'sein'::text,'Da sind heute viele Kisten um den Arbeiter herum.'::text),
(328327,36481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Навколо працівника сьогодні ... багато коробок.'::text,'є'::text,'є'::text,'бути'::text,'Навколо працівника сьогодні є багато коробок.'::text),
