(328325,36481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aujourd''hui, ... beaucoup de cartons autour de l''employé.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Aujourd''hui, il y a beaucoup de cartons autour de l''employé.'::text),
(328328,36481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün işçinin etrafında çok kutu ...'::text,'var'::text,'var'::text,'olmak'::text,'Bugün işçinin etrafında çok kutu var.'::text),
(328329,36481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma sok doboz ... a dolgozó körül.'::text,'van'::text,'van'::text,'lenni'::text,'Ma sok doboz van a dolgozó körül.'::text),
(309522,34392,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das letzte Teil in der Mitte finden.'::text,'kann'::text,'kann'::text,'kann'::text,'Sie kann das letzte Teil in der Mitte finden.'::text),
(309526,34392,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... знайти останній пазл посередині.'::text,'може'::text,'може'::text,'може'::text,'Вона може знайти останній пазл посередині.'::text),
(309525,34392,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... encontrar la última pieza en el centro.'::text,'puede'::text,'puede'::text,'puede'::text,'Ella puede encontrar la última pieza en el centro.'::text),
(309524,34392,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... trouver la dernière pièce au milieu.'::text,'peut'::text,'peut'::text,'peut'::text,'Elle peut trouver la dernière pièce au milieu.'::text),
(309527,34392,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ortadaki son parçayı ...'::text,'bulabilir'::text,'bulabilir'::text,'bulabilir'::text,'O ortadaki son parçayı bulabilir.'::text),
