(309554,34395,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun tüm yapboz parçaları için fazla ... yok.'::text,'yeri'::text,'yerleri'::text,'bir yeri'::text,'Onun tüm yapboz parçaları için fazla yeri yok.'::text),
(309555,34395,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki nincs sok ... az összes kirakódarabhoz.'::text,'helye'::text,'helye'::text,'egy helye'::text,'Neki nincs sok helye az összes kirakódarabhoz.'::text),
(303726,33748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hört sie sich jetzt an? Einen Wasserfall! Das ist absolut furchterregend!'::text,'Was'::text,'Wo'::text,'Wann'::text,'Was hört sie sich jetzt an? Einen Wasserfall! Das ist absolut furchterregend!'::text),
(303730,33748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона зараз слухає? Водоспад! Це просто жах!'::text,'Що'::text,'Де'::text,'Коли'::text,'Що вона зараз слухає? Водоспад! Це просто жах!'::text),
(303729,33748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... escucha ella ahora? ¡Una cascada! ¡Es absolutamente aterrador!'::text,'Qué'::text,'Dónde'::text,'Cuándo'::text,'¿Qué escucha ella ahora? ¡Una cascada! ¡Es absolutamente aterrador!'::text),
(303728,33748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle écoute ... maintenant ? Une cascade ! C''est absolument terrifiant !'::text,'quoi'::text,'où'::text,'quand'::text,'Elle écoute quoi maintenant ? Une cascade ! C''est absolument terrifiant !'::text),
(303731,33748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şimdi ... dinliyor? Bir şelale! Resmen dehşet verici!'::text,'ne'::text,'nerede'::text,'ne zaman'::text,'O şimdi ne dinliyor? Bir şelale! Resmen dehşet verici!'::text),
(303732,33748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hallgat ő most? Egy vízesést! Ez abszolút ijesztő!'::text,'Mit'::text,'Hol'::text,'Mikor'::text,'Mit hallgat ő most? Egy vízesést! Ez abszolút ijesztő!'::text),
(303762,33752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hört oft Vögeln zu, aber jetzt ... sie einem Bach zu.'::text,'hört'::text,'hört'::text,NULL::text,'Sie hört oft Vögeln zu, aber jetzt hört sie einem Bach zu.'::text),
(303766,33752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона часто слухає птахів, але зараз вона ... струмок.'::text,'слухає'::text,'слухає'::text,NULL::text,'Вона часто слухає птахів, але зараз вона слухає струмок.'::text),
(303765,33752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella suele escuchar pájaros, pero ahora ... un arroyo.'::text,'está escuchando'::text,'escucha'::text,NULL::text,'Ella suele escuchar pájaros, pero ahora está escuchando un arroyo.'::text),
(303764,33752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle écoute souvent les oiseaux, mais là, elle ... un ruisseau.'::text,'est en train d''écouter'::text,'écoute'::text,NULL::text,'Elle écoute souvent les oiseaux, mais là, elle est en train d''écouter un ruisseau.'::text),
(303767,33752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sık sık kuşları dinler ama şimdi bir dereyi ...'::text,'dinliyor'::text,'dinler'::text,NULL::text,'O sık sık kuşları dinler ama şimdi bir dereyi dinliyor.'::text),
(303768,33752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő gyakran hallgatja a madarakat, de most egy patakot ...'::text,'hallgat'::text,'hallgat'::text,NULL::text,'Ő gyakran hallgatja a madarakat, de most egy patakot hallgat.'::text),
(309846,34428,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... Plan braucht bald eine größere Wand.'::text,'dieser'::text,'diese'::text,'jene'::text,'Alter, dieser Plan braucht bald eine größere Wand.'::text),
(309850,34428,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... план потребуватиме більшої стіни.'::text,'цей'::text,'ці'::text,'ті'::text,'Бро, цей план потребуватиме більшої стіни.'::text),
(309849,34428,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... plan va a necesitar una pared más grande.'::text,'este'::text,'estos'::text,'esos'::text,'Tío, este plan va a necesitar una pared más grande.'::text),
(309848,34428,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ... plan va avoir besoin d''un mur plus grand.'::text,'ce'::text,'ces'::text,'ces'::text,'Mec, ce plan va avoir besoin d''un mur plus grand.'::text),
(309851,34428,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... planın daha büyük bir duvara ihtiyacı olacak.'::text,'bu'::text,'bu'::text,'şu'::text,'Kanka, bu planın daha büyük bir duvara ihtiyacı olacak.'::text),
(309852,34428,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a tervhez nagyobb fal kell majd.'::text,'ehhez'::text,'ezekhez'::text,'azokhoz'::text,'Tesó, ehhez a tervhez nagyobb fal kell majd.'::text),
(309882,34432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hunderte Notizen! Dieser Plan braucht so viel ..., ein Albtraum!'::text,'Zeit'::text,'Zeit'::text,'eine Zeit'::text,'Hunderte Notizen! Dieser Plan braucht so viel Zeit, ein Albtraum!'::text),
(309886,34432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сотні нотаток! Цей план потребує стільки ..., це жах!'::text,'часу'::text,'часу'::text,'часу'::text,'Сотні нотаток! Цей план потребує стільки часу, це жах!'::text),
(309885,34432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cientos de notas! ¡Este plan necesita tanto ..., es una pesadilla!'::text,'tiempo'::text,'tiempo'::text,'un tiempo'::text,'¡Cientos de notas! ¡Este plan necesita tanto tiempo, es una pesadilla!'::text),
(309884,34432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des centaines de notes ! Ce plan demande tellement de ..., c''est un cauchemar !'::text,'temps'::text,'temps'::text,'un temps'::text,'Des centaines de notes ! Ce plan demande tellement de temps, c''est un cauchemar !'::text),
(309887,34432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzlerce not! Bu plan o kadar çok ... istiyor ki, kâbus gibi!'::text,'zaman'::text,'zamanlar'::text,'bir zaman'::text,'Yüzlerce not! Bu plan o kadar çok zaman istiyor ki, kâbus gibi!'::text),
(309888,34432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Több száz cetli! Ez a terv annyi ... igényel, rémálom!'::text,'időt'::text,'időt'::text,'egy időt'::text,'Több száz cetli! Ez a terv annyi időt igényel, rémálom!'::text),
(325308,36146,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Büro ist sonst ruhig, aber jetzt ... dort eine Band in Uniformen.'::text,'spielt'::text,'spielt'::text,NULL::text,'Ihr Büro ist sonst ruhig, aber jetzt spielt dort eine Band in Uniformen.'::text),
(325312,36146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її офіс зазвичай тихий, але зараз там ... оркестр в уніформі.'::text,'грає'::text,'грає'::text,NULL::text,'Її офіс зазвичай тихий, але зараз там грає оркестр в уніформі.'::text),
(325311,36146,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su oficina suele estar tranquila, pero ahora una banda con uniformes ... allí.'::text,'está tocando'::text,'toca'::text,NULL::text,'Su oficina suele estar tranquila, pero ahora una banda con uniformes está tocando allí.'::text),
(325310,36146,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son bureau est d''habitude calme, mais là, une fanfare en uniforme ... dedans.'::text,'est en train de jouer'::text,'joue'::text,NULL::text,'Son bureau est d''habitude calme, mais là, une fanfare en uniforme est en train de jouer dedans.'::text),
(325313,36146,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun ofisi genelde sessizdir ama şimdi orada üniformalı bir bando ...'::text,'çalıyor'::text,'çalar'::text,NULL::text,'Onun ofisi genelde sessizdir ama şimdi orada üniformalı bir bando çalıyor.'::text),
(325314,36146,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az irodája általában csendes, de most egy egyenruhás zenekar ... ott.'::text,'játszik'::text,'játszik'::text,NULL::text,'Az irodája általában csendes, de most egy egyenruhás zenekar játszik ott.'::text),
(311664,34630,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du stempelst ... auf jede Karte? Top-Bewertung, Respekt.'::text,'5 Sterne'::text,'5 Stern'::text,'5 Sterne'::text,'Du stempelst 5 Sterne auf jede Karte? Top-Bewertung, Respekt.'::text),
(311668,34630,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ставиш ... на кожну картку? Топовий рейтинг, респект.'::text,'5 зірок'::text,'5 зірку'::text,'5 зірок'::text,'Ти ставиш 5 зірок на кожну картку? Топовий рейтинг, респект.'::text),
(311667,34630,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Tú pones ... en cada tarjeta? Nota máxima, respeto.'::text,'5 estrellas'::text,'5 estrella'::text,'5 estrellas'::text,'¿Tú pones 5 estrellas en cada tarjeta? Nota máxima, respeto.'::text),
(311666,34630,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu tamponnes ... sur chaque carte ? Note maximale, respect.'::text,'5 étoiles'::text,'5 étoile'::text,'5 étoiles'::text,'Tu tamponnes 5 étoiles sur chaque carte ? Note maximale, respect.'::text),
(311669,34630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen her karta ... mı basıyorsun? Tam puan, saygılar.'::text,'5 yıldız'::text,'5 yıldız'::text,'5 yıldızlar'::text,'Sen her karta 5 yıldız mı basıyorsun? Tam puan, saygılar.'::text),
(311670,34630,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... pecsételsz minden kártyára? Csúcsértékelés, respekt.'::text,'5 csillagot'::text,'5 csillagot'::text,'5 csillagot'::text,'Te 5 csillagot pecsételsz minden kártyára? Csúcsértékelés, respekt.'::text),
(311682,34632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Regel, klar: Jede Schale ... fünf Sterne bekommen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Tolle Regel, klar: Jede Schale muss fünf Sterne bekommen.'::text),
(311686,34632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудове правило, звісно: кожна миска ... отримати п''ять зірок.'::text,'має'::text,'мусить'::text,'мала б'::text,'Чудове правило, звісно: кожна миска має отримати п''ять зірок.'::text),
(311685,34632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué gran regla, obvio: cada cuenco ... recibir cinco estrellas.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Qué gran regla, obvio: cada cuenco tiene que recibir cinco estrellas.'::text),
(311684,34632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super règle, évidemment : chaque bol ... recevoir cinq étoiles.'::text,'doit'::text,'doit'::text,'devrait'::text,'Super règle, évidemment : chaque bol doit recevoir cinq étoiles.'::text),
(311687,34632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika kural, tabii: her kase beş yıldız ...'::text,'almak zorunda'::text,'almalı'::text,'almalı'::text,'Harika kural, tabii: her kase beş yıldız almak zorunda.'::text),
(311688,34632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek szabály, persze: minden tálnak ötcsillagos értékelést ... kapnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'Remek szabály, persze: minden tálnak ötcsillagos értékelést kell kapnia.'::text),
(324345,36039,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du wartest an der Ampel, während ... Läufer vorbeilaufen. Respekt.'::text,'zwanzig'::text,'zwanzigste'::text,'Zwanziger'::text,'Du wartest an der Ampel, während zwanzig Läufer vorbeilaufen. Respekt.'::text),
(324349,36039,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти чекаєш на світлофорі, поки повз пробігають ... бігунів. Респект.'::text,'двадцять'::text,'двадцятий'::text,'двадцятки'::text,'Ти чекаєш на світлофорі, поки повз пробігають двадцять бігунів. Респект.'::text),
(324348,36039,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú esperas en el semáforo mientras pasan ... corredores. Respeto.'::text,'veinte'::text,'vigésimo'::text,'veinte'::text,'Tú esperas en el semáforo mientras pasan veinte corredores. Respeto.'::text),
(324347,36039,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu attends au feu pendant que ... coureurs passent. Respect.'::text,'vingt'::text,'vingtième'::text,'vingt'::text,'Tu attends au feu pendant que vingt coureurs passent. Respect.'::text),
(324350,36039,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen ... koşucu geçerken trafik ışığında bekliyorsun. Saygılar.'::text,'yirmi'::text,'yirminci'::text,'yirmiler'::text,'Sen yirmi koşucu geçerken trafik ışığında bekliyorsun. Saygılar.'::text),
(324351,36039,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te a lámpánál vársz, amíg ... futó elhalad. Respekt.'::text,'húsz'::text,'huszadik'::text,'húszasok'::text,'Te a lámpánál vársz, amíg húsz futó elhalad. Respekt.'::text),
(324363,36041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise fährt sie weiter, aber gestern ... sie an der Ampel.'::text,'hielt'::text,'hält'::text,NULL::text,'Normalerweise fährt sie weiter, aber gestern hielt sie an der Ampel.'::text),
(324367,36041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона їде далі, але вчора вона ... на світлофорі.'::text,'зупинилася'::text,'зупиняється'::text,NULL::text,'Зазвичай вона їде далі, але вчора вона зупинилася на світлофорі.'::text),
(324366,36041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente ella sigue pedaleando, pero ayer ... en el semáforo.'::text,'paró'::text,'para'::text,NULL::text,'Normalmente ella sigue pedaleando, pero ayer paró en el semáforo.'::text),
(324365,36041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, elle continue, mais hier elle ... au feu.'::text,'s''est arrêtée'::text,'s''arrête'::text,NULL::text,'D''habitude, elle continue, mais hier elle s''est arrêtée au feu.'::text),
(324368,36041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O genelde yoluna devam eder ama dün trafik ışığında ...'::text,'durdu'::text,'durur'::text,NULL::text,'O genelde yoluna devam eder ama dün trafik ışığında durdu.'::text),
(324369,36041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő általában továbbteker, de tegnap ... a lámpánál.'::text,'megállt'::text,'megáll'::text,NULL::text,'Ő általában továbbteker, de tegnap megállt a lámpánál.'::text),
(324840,36094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Lkw ist nicht mehr ... Platz.'::text,'viel'::text,'viele'::text,'etwas'::text,'Im Lkw ist nicht mehr viel Platz.'::text),
(324844,36094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У вантажівці вже не лишилося ... місця.'::text,'багато'::text,'багато'::text,'трохи'::text,'У вантажівці вже не лишилося багато місця.'::text),
(324843,36094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No queda ... espacio en el camión.'::text,'mucho'::text,'muchos'::text,'algo de'::text,'No queda mucho espacio en el camión.'::text),
(324842,36094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne reste pas ... place dans le camion.'::text,'beaucoup de'::text,'beaucoup de'::text,'de la'::text,'Il ne reste pas beaucoup de place dans le camion.'::text),
(324845,36094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamyonda ... yer kalmadı.'::text,'çok'::text,'çok'::text,'biraz'::text,'Kamyonda çok yer kalmadı.'::text),
(324846,36094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem maradt ... hely a teherautóban.'::text,'sok'::text,'sok'::text,'némi'::text,'Nem maradt sok hely a teherautóban.'::text),
(316848,35206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bruh, ... sitzen denn alle? Der Saal ist rappelvoll.'::text,'Wo'::text,'Was'::text,'Wer'::text,'Bruh, Wo sitzen denn alle? Der Saal ist rappelvoll.'::text),
(316852,35206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... всі сидітимуть? Зала забита.'::text,'Де'::text,'Що'::text,'Хто'::text,'Бро, Де всі сидітимуть? Зала забита.'::text),
(316851,35206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ¿... se va a sentar todo el mundo? La sala está llena.'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'Bro, ¿Dónde se va a sentar todo el mundo? La sala está llena.'::text),
(316850,35206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ... tout le monde va s''asseoir ? La salle est pleine.'::text,'Où'::text,'Quoi'::text,'Qui'::text,'Mec, Où tout le monde va s''asseoir ? La salle est pleine.'::text),
(316853,35206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, herkes ... oturacak? Salon tıklım tıklım.'::text,'nerede'::text,'ne'::text,'kim'::text,'Kanka, herkes nerede oturacak? Salon tıklım tıklım.'::text),
(316854,35206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... fog ülni mindenki? Tele van a terem.'::text,'Hol'::text,'Mi'::text,'Ki'::text,'Tesó, Hol fog ülni mindenki? Tele van a terem.'::text),
(316884,35210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... öfter in der Mitte sitzen, ehrlich. Super Platz.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Du solltest öfter in der Mitte sitzen, ehrlich. Super Platz.'::text),
(316888,35210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... частіше сидіти посередині, чесно. Класне місце.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Ти мала б частіше сидіти посередині, чесно. Класне місце.'::text),
(316887,35210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... sentarte en el medio más a menudo, en serio. Buen sitio.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Tú deberías sentarte en el medio más a menudo, en serio. Buen sitio.'::text),
(316886,35210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... t''asseoir au milieu plus souvent, franchement. Super place.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Tu devrais t''asseoir au milieu plus souvent, franchement. Super place.'::text),
(316889,35210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen daha sık ortada ..., cidden. Harika yer.'::text,'oturmalısın'::text,'oturmalısın'::text,'oturmalısın'::text,'Sen daha sık ortada oturmalısın, cidden. Harika yer.'::text),
(316890,35210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neked gyakrabban ... középre ülnöd, őszintén. Remek hely.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Neked gyakrabban kellene középre ülnöd, őszintén. Remek hely.'::text),
(312906,34768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quartalsupdate: Die Türen ... einen Ausblick im Wert von 2 Millionen Euro.'::text,'enthüllen'::text,'enthüllt'::text,'enthüllend'::text,'Quartalsupdate: Die Türen enthüllen einen Ausblick im Wert von 2 Millionen Euro.'::text),
(312910,34768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Квартальний звіт: двері ... краєвид вартістю 2 мільйони євро.'::text,'відкривають'::text,'відкриває'::text,'відкриваючи'::text,'Квартальний звіт: двері відкривають краєвид вартістю 2 мільйони євро.'::text),
