(312911,34768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çeyrek güncellemesi: kapılar 2 milyon euro değerinde bir manzarayı ...'::text,'ortaya çıkarır'::text,'ortaya çıkarır'::text,'ortaya çıkararak'::text,'Çeyrek güncellemesi: kapılar 2 milyon euro değerinde bir manzarayı ortaya çıkarır.'::text),
(312912,34768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negyedéves jelentés: az ajtók egy 2 millió eurót érő kilátást ...'::text,'tárnak fel'::text,'tár fel'::text,'feltáró'::text,'Negyedéves jelentés: az ajtók egy 2 millió eurót érő kilátást tárnak fel.'::text),
(312969,34775,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Türen sind jetzt offen, ... zeigen sie das ganze Tal, echt.'::text,'also'::text,'weil'::text,'aber'::text,'Alter, die Türen sind jetzt offen, also zeigen sie das ganze Tal, echt.'::text),
(312973,34775,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, двері вже відчинені, ... вони відкривають усю долину, чесно.'::text,'тому'::text,'бо'::text,'але'::text,'Бро, двері вже відчинені, тому вони відкривають усю долину, чесно.'::text),
(312972,34775,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, las puertas ya están abiertas, ... dejan ver todo el valle, en serio.'::text,'así que'::text,'porque'::text,'pero'::text,'Tío, las puertas ya están abiertas, así que dejan ver todo el valle, en serio.'::text),
(312971,34775,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, les portes sont ouvertes maintenant, ... elles révèlent toute la vallée, sérieux.'::text,'donc'::text,'parce que'::text,'mais'::text,'Mec, les portes sont ouvertes maintenant, donc elles révèlent toute la vallée, sérieux.'::text),
(312974,34775,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kapılar artık açık, ... bütün vadiyi gözler önüne seriyorlar, cidden.'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Kanka, kapılar artık açık, bu yüzden bütün vadiyi gözler önüne seriyorlar, cidden.'::text),
(312975,34775,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az ajtók már nyitva vannak, ... az egész völgyet feltárják, komolyan.'::text,'ezért'::text,'mert'::text,'de'::text,'Tesó, az ajtók már nyitva vannak, ezért az egész völgyet feltárják, komolyan.'::text),
(310116,34458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand ... es aufhalten! Hunderte Leute zeigen in den Himmel!'::text,'kann'::text,'kann'::text,'ist'::text,'Niemand kann es aufhalten! Hunderte Leute zeigen in den Himmel!'::text),
(310120,34458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто не ... це зупинити! Сотні людей показують на небо!'::text,'може'::text,'може'::text,'є'::text,'Ніхто не може це зупинити! Сотні людей показують на небо!'::text),
(310119,34458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nadie ... pararlo! ¡Cientos de personas señalan al cielo!'::text,'puede'::text,'puede'::text,'está'::text,'¡Nadie puede pararlo! ¡Cientos de personas señalan al cielo!'::text),
(310118,34458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne ne ... l''arrêter ! Des centaines de gens montrent le ciel du doigt !'::text,'peut'::text,'peut'::text,'est'::text,'Personne ne peut l''arrêter ! Des centaines de gens montrent le ciel du doigt !'::text),
(310121,34458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse bunu ...! Yüzlerce insan gökyüzünü gösteriyor!'::text,'durduramaz'::text,'durduramaz'::text,NULL::text,'Kimse bunu durduramaz! Yüzlerce insan gökyüzünü gösteriyor!'::text),
(310122,34458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki sem ... megállítani! Emberek százai mutatnak az égre!'::text,'tudja'::text,'tudja'::text,'van'::text,'Senki sem tudja megállítani! Emberek százai mutatnak az égre!'::text),
(310170,34464,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie zeigen nach oben, ... das Ding am Himmel ist.'::text,'weil'::text,'aber'::text,'also'::text,'Sie zeigen nach oben, weil das Ding am Himmel ist.'::text),
(310174,34464,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони показують угору, ... та штука в небі.'::text,'бо'::text,'але'::text,'тому'::text,'Вони показують угору, бо та штука в небі.'::text),
(310173,34464,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos señalan hacia arriba ... la cosa está en el cielo.'::text,'porque'::text,'pero'::text,'así que'::text,'Ellos señalan hacia arriba porque la cosa está en el cielo.'::text),
(310172,34464,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils montrent vers le haut ... la chose est dans le ciel.'::text,'parce que'::text,'mais'::text,'donc'::text,'Ils montrent vers le haut parce que la chose est dans le ciel.'::text),
(310175,34464,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar yukarıyı gösteriyor ... o şey gökyüzünde.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Onlar yukarıyı gösteriyor çünkü o şey gökyüzünde.'::text),
