(313288,34810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... дзвонити в той дзвоник гучніше, чесно. Уся закусочна це обожнює.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Ти мав би дзвонити в той дзвоник гучніше, чесно. Уся закусочна це обожнює.'::text),
(313287,34810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... tocar esa campana más fuerte, en serio. A todo el diner le encanta.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Tú deberías tocar esa campana más fuerte, en serio. A todo el diner le encanta.'::text),
(313286,34810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... sonner cette cloche plus fort, franchement. Tout le diner adore ça.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Tu devrais sonner cette cloche plus fort, franchement. Tout le diner adore ça.'::text),
(313289,34810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen o zili daha yüksek sesle ..., cidden. Bütün lokanta buna bayılıyor.'::text,'çalmalısın'::text,'çalmalısın'::text,'çalmalısın'::text,'Sen o zili daha yüksek sesle çalmalısın, cidden. Bütün lokanta buna bayılıyor.'::text),
(313290,34810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neked hangosabban ... csengetned, őszintén. Az egész büfé imádja.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Neked hangosabban kellene csengetned, őszintén. Az egész büfé imádja.'::text),
(326154,36240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mann, die Kellnerin trägt ..., weil sie schnell sein muss.'::text,'3 Teller'::text,'3 Teller'::text,'3 Teller'::text,'Mann, die Kellnerin trägt 3 Teller, weil sie schnell sein muss.'::text),
(326158,36240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, офіціантка несе ..., бо мусить бути швидкою.'::text,'3 тарілки'::text,'3 тарілку'::text,'3 тарілки'::text,'Чувак, офіціантка несе 3 тарілки, бо мусить бути швидкою.'::text),
(326157,36240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la camarera lleva ... porque tiene que ser rápida.'::text,'3 platos'::text,'3 plato'::text,'3 platos'::text,'Tío, la camarera lleva 3 platos porque tiene que ser rápida.'::text),
(326156,36240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, la serveuse porte ... parce qu''elle doit être rapide.'::text,'3 assiettes'::text,'3 assiette'::text,'3 assiettes'::text,'Mec, la serveuse porte 3 assiettes parce qu''elle doit être rapide.'::text),
(326159,36240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, garson kız ... taşıyor çünkü hızlı olmak zorunda.'::text,'3 tabak'::text,'3 tabak'::text,'3 tabaklar'::text,'Kanka, garson kız 3 tabak taşıyor çünkü hızlı olmak zorunda.'::text),
(326160,36240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a pincérnő ... visz, mert gyorsnak kell lennie.'::text,'3 tányért'::text,'3 tányért'::text,'3 tányért'::text,'Tesó, a pincérnő 3 tányért visz, mert gyorsnak kell lennie.'::text),
(326190,36244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Kellnerin hat keine ... mehr für den Kaffee!'::text,'Milch'::text,'Milch'::text,'eine Milch'::text,'Katastrophe! Die Kellnerin hat keine Milch mehr für den Kaffee!'::text),
(326194,36244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! В офіціантки більше немає ... для кави!'::text,'молока'::text,'молока'::text,'молока'::text,'Катастрофа! В офіціантки більше немає молока для кави!'::text),
(326193,36244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Catástrofe! ¡A la camarera no le queda más ... para el café!'::text,'leche'::text,'leche'::text,'una leche'::text,'¡Catástrofe! ¡A la camarera no le queda más leche para el café!'::text),
(326192,36244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! La serveuse n''a plus de ... pour le café !'::text,'lait'::text,'lait'::text,'un lait'::text,'Catastrophe ! La serveuse n''a plus de lait pour le café !'::text),
(326195,36244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Garsonun kahve için hiç ... kalmadı!'::text,'sütü'::text,'sütleri'::text,'bir sütü'::text,'Felaket! Garsonun kahve için hiç sütü kalmadı!'::text),
(326196,36244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A pincérnőnek nincs több ... a kávéhoz!'::text,'teje'::text,'teje'::text,'egy teje'::text,'Katasztrófa! A pincérnőnek nincs több teje a kávéhoz!'::text),
(297129,33015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist das Brot golden? Weil es eine goldene Farbe hat.'::text,'Warum'::text,'Wer'::text,'Wo'::text,'Warum ist das Brot golden? Weil es eine goldene Farbe hat.'::text),
(297133,33015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... буханець золотистий? Бо він має золотистий колір.'::text,'Чому'::text,'Хто'::text,'Де'::text,'Чому буханець золотистий? Бо він має золотистий колір.'::text),
(297132,33015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está dorada la hogaza? Porque tiene un color dorado.'::text,'Por qué'::text,'Quién'::text,'Dónde'::text,'¿Por qué está dorada la hogaza? Porque tiene un color dorado.'::text),
(297131,33015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la miche est-elle dorée ? Parce qu''elle a une couleur dorée.'::text,'Pourquoi'::text,'Qui'::text,'Où'::text,'Pourquoi la miche est-elle dorée ? Parce qu''elle a une couleur dorée.'::text),
(297134,33015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Somun ... altın rengi? Çünkü rengi altın gibi.'::text,'neden'::text,'kim'::text,'nerede'::text,'Somun neden altın rengi? Çünkü rengi altın gibi.'::text),
(297135,33015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... aranyszínű a cipó? Mert aranyszínű a színe.'::text,'Miért'::text,'Ki'::text,'Hol'::text,'Miért aranyszínű a cipó? Mert aranyszínű a színe.'::text),
(297174,33020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Brot ist ... als der blasse Teig.'::text,'goldener'::text,'goldener'::text,'am goldensten'::text,'Das Brot ist goldener als der blasse Teig.'::text),
(297178,33020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Буханець ... за бліде тісто.'::text,'більш золотистий'::text,'золотистіший'::text,'найзолотистіший'::text,'Буханець більш золотистий за бліде тісто.'::text),
(297177,33020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La hogaza es ... que la masa pálida.'::text,'más dorada'::text,'más dorada'::text,'la más dorada'::text,'La hogaza es más dorada que la masa pálida.'::text),
(297176,33020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La miche est ... que la pâte pâle.'::text,'plus dorée'::text,'plus dorée'::text,'la plus dorée'::text,'La miche est plus dorée que la pâte pâle.'::text),
(297179,33020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Somun soluk hamurdan ...'::text,'daha altın rengi'::text,'daha altın rengi'::text,'en altın rengi'::text,'Somun soluk hamurdan daha altın rengi.'::text),
(297180,33020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cipó ..., mint a sápadt tészta.'::text,'aranyszínűbb'::text,'aranyszínűbb'::text,'legaranyszínűbb'::text,'A cipó aranyszínűbb, mint a sápadt tészta.'::text),
(294672,32742,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unten wartet ein Mann. Der Feuerwehrmann gibt die Katze ... Mann.'::text,'dem'::text,'einem'::text,'einem'::text,'Unten wartet ein Mann. Der Feuerwehrmann gibt die Katze dem Mann.'::text),
(294676,32742,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Унизу чекає чоловік. Пожежник віддає кота ... чоловікові.'::text,''::text,NULL::text,NULL::text,'Унизу чекає чоловік. Пожежник віддає кота чоловікові.'::text),
(294675,32742,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un hombre espera abajo. El bombero le da el gato ... hombre.'::text,'al'::text,'a un'::text,'a un'::text,'Un hombre espera abajo. El bombero le da el gato al hombre.'::text),
(294674,32742,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un homme attend en bas. Le pompier donne le chat ... homme.'::text,'à l'''::text,'à un'::text,'à un'::text,'Un homme attend en bas. Le pompier donne le chat à l'' homme.'::text),
(294677,32742,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşağıda bir adam bekliyor. İtfaiyeci kediyi ... adama veriyor.'::text,''::text,'bir'::text,'bir'::text,'Aşağıda bir adam bekliyor. İtfaiyeci kediyi adama veriyor.'::text),
(294678,32742,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lent vár egy férfi. A tűzoltó odaadja a macskát ... férfinak.'::text,'a'::text,'egy'::text,'egy'::text,'Lent vár egy férfi. A tűzoltó odaadja a macskát a férfinak.'::text),
(294717,32747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Katze steckt fest! Der Feuerwehrmann ... sie retten, versprochen!'::text,'wird'::text,'rettet'::text,'rettete'::text,'Katastrophe! Die Katze steckt fest! Der Feuerwehrmann wird sie retten, versprochen!'::text),
(294721,32747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Кіт застряг! Пожежник ... його, обіцяю!'::text,'врятує'::text,'рятує'::text,'врятував'::text,'Катастрофа! Кіт застряг! Пожежник врятує його, обіцяю!'::text),
(294720,32747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡El gato está atrapado! ¡El bombero lo ..., te lo prometo!'::text,'salvará'::text,'salva'::text,'salvó'::text,'¡Desastre! ¡El gato está atrapado! ¡El bombero lo salvará, te lo prometo!'::text),
(294719,32747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Désastre ! Le chat est coincé ! Le pompier le ..., je te le promets !'::text,'sauvera'::text,'sauve'::text,'a sauvé'::text,'Désastre ! Le chat est coincé ! Le pompier le sauvera, je te le promets !'::text),
(294722,32747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Kedi sıkıştı! İtfaiyeci onu ..., söz veriyorum!'::text,'kurtaracak'::text,'kurtarır'::text,'kurtardı'::text,'Felaket! Kedi sıkıştı! İtfaiyeci onu kurtaracak, söz veriyorum!'::text),
(294723,32747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A macska beszorult! A tűzoltó ... őt, ígérem!'::text,'meg fogja menteni'::text,'megmenti'::text,'megmentette'::text,'Katasztrófa! A macska beszorult! A tűzoltó meg fogja menteni őt, ígérem!'::text),
(316803,35201,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr bescheiden, klar: Sie sagt sich: „Ich ... lauter singen als alle anderen.“'::text,'muss'::text,'muss'::text,'sollte'::text,'Sehr bescheiden, klar: Sie sagt sich: „Ich muss lauter singen als alle anderen.“'::text),
(316807,35201,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже скромно, звісно: вона каже собі: «Я ... співати голосніше за всіх».'::text,'мушу'::text,'маю'::text,'мала б'::text,'Дуже скромно, звісно: вона каже собі: «Я мушу співати голосніше за всіх».'::text),
(316806,35201,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy humilde, obvio: ella se dice: «Yo ... cantar más fuerte que todos».'::text,'debo'::text,'tengo que'::text,'debería'::text,'Muy humilde, obvio: ella se dice: «Yo debo cantar más fuerte que todos».'::text),
(316805,35201,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très modeste, évidemment : elle se dit : « Je ... chanter plus fort que tout le monde. »'::text,'dois'::text,'dois'::text,'devrais'::text,'Très modeste, évidemment : elle se dit : « Je dois chanter plus fort que tout le monde. »'::text),
(316808,35201,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok alçakgönüllü, tabii: kendine “Ben herkesten daha yüksek sesle ...” diyor.'::text,'şarkı söylemeliyim'::text,'şarkı söylemek zorundayım'::text,'şarkı söylemeliyim'::text,'Çok alçakgönüllü, tabii: kendine “Ben herkesten daha yüksek sesle şarkı söylemeliyim” diyor.'::text),
(316809,35201,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon szerény, persze: azt mondja magának: „Nekem mindenkinél hangosabban ... énekelnem.”'::text,'kell'::text,'kell'::text,'kellene'::text,'Nagyon szerény, persze: azt mondja magának: „Nekem mindenkinél hangosabban kell énekelnem.”'::text),
(300288,33366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund wartet, also ... er jeden Tag früh nach Hause kommen.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Der Hund wartet, also sollte er jeden Tag früh nach Hause kommen.'::text),
(300292,33366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес чекає, тож він ... щодня приходити додому рано.'::text,'мав би'::text,'мав би'::text,'буде'::text,'Пес чекає, тож він мав би щодня приходити додому рано.'::text),
(300291,33366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro espera, así que él ... volver a casa temprano cada día.'::text,'debería'::text,'debería'::text,'deberá'::text,'El perro espera, así que él debería volver a casa temprano cada día.'::text),
(300290,33366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien attend, alors il ... rentrer tôt tous les jours.'::text,'devrait'::text,'devrait'::text,'devra'::text,'Le chien attend, alors il devrait rentrer tôt tous les jours.'::text),
(300293,33366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek bekliyor, bu yüzden o her gün eve erken ...'::text,'gelmeli'::text,'gelmeli'::text,'gelecek'::text,'Köpek bekliyor, bu yüzden o her gün eve erken gelmeli.'::text),
(300294,33366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya vár, ezért neki minden nap korán ... hazajönnie.'::text,'kellene'::text,'kellene'::text,'kell'::text,'A kutya vár, ezért neki minden nap korán kellene hazajönnie.'::text),
(325821,36203,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Der Besuch endet ... acht Uhr, und sie ist gerade erst angekommen!'::text,'um'::text,'am'::text,'im'::text,'Albtraum! Der Besuch endet um acht Uhr, und sie ist gerade erst angekommen!'::text),
(325825,36203,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Відвідування закінчується ... восьмій, а вона щойно прийшла!'::text,'о'::text,'на'::text,'у'::text,'Жах! Відвідування закінчується о восьмій, а вона щойно прийшла!'::text),
(325824,36203,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡La visita termina ... las ocho y ella acaba de llegar!'::text,'a'::text,'sobre'::text,'en'::text,'¡Pesadilla! ¡La visita termina a las ocho y ella acaba de llegar!'::text),
(325823,36203,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! La visite se termine ... huit heures, et elle vient juste d''arriver !'::text,'à'::text,'sur'::text,'dans'::text,'Cauchemar ! La visite se termine à huit heures, et elle vient juste d''arriver !'::text),
(325826,36203,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Ziyaret saat ... bitiyor ve o daha yeni geldi!'::text,'sekizde'::text,'sekizde'::text,'sekizde'::text,'Kâbus! Ziyaret saat sekizde bitiyor ve o daha yeni geldi!'::text),
(325827,36203,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A látogatás ... ér véget, és ő épp csak megérkezett!'::text,'nyolckor'::text,'nyolcon'::text,'nyolcban'::text,'Rémálom! A látogatás nyolckor ér véget, és ő épp csak megérkezett!'::text),
(325839,36205,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Sie hat keine ... für einen langen Besuch!'::text,'Zeit'::text,'Zeit'::text,'eine Zeit'::text,'Katastrophe! Sie hat keine Zeit für einen langen Besuch!'::text),
(325843,36205,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Вона не має ... на довгий візит!'::text,'часу'::text,'часу'::text,'часу'::text,'Катастрофа! Вона не має часу на довгий візит!'::text),
(325842,36205,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Ella no tiene ... para una visita larga!'::text,'tiempo'::text,'tiempo'::text,'un tiempo'::text,'¡Desastre! ¡Ella no tiene tiempo para una visita larga!'::text),
(325841,36205,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Désastre ! Elle n''a pas de ... pour une longue visite !'::text,'temps'::text,'temps'::text,'un temps'::text,'Désastre ! Elle n''a pas de temps pour une longue visite !'::text),
(325844,36205,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Onun uzun bir ziyaret için ... yok!'::text,'zamanı'::text,'zamanları'::text,'bir zamanı'::text,'Felaket! Onun uzun bir ziyaret için zamanı yok!'::text),
(325845,36205,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Neki nincs ... egy hosszú látogatásra!'::text,'ideje'::text,'ideje'::text,'egy ideje'::text,'Katasztrófa! Neki nincs ideje egy hosszú látogatásra!'::text),
(311961,34663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hilfe! ... ist die Rezeption? Ich habe mich total verlaufen!'::text,'Wo'::text,'Was'::text,'Wer'::text,'Hilfe! Wo ist die Rezeption? Ich habe mich total verlaufen!'::text),
(311965,34663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рятуйте! ... рецепція? Я зовсім заблукала!'::text,'Де'::text,'Що'::text,'Хто'::text,'Рятуйте! Де рецепція? Я зовсім заблукала!'::text),
(311964,34663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Socorro! ¿... está la recepción? ¡Yo estoy totalmente perdida!'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'¡Socorro! ¿Dónde está la recepción? ¡Yo estoy totalmente perdida!'::text),
(311963,34663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À l''aide ! ... est la réception ? Je suis complètement perdue !'::text,'Où'::text,'Quoi'::text,'Qui'::text,'À l''aide ! Où est la réception ? Je suis complètement perdue !'::text),
(311966,34663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İmdat! Resepsiyon ...? Ben tamamen kayboldum!'::text,'nerede'::text,'ne'::text,'kim'::text,'İmdat! Resepsiyon nerede? Ben tamamen kayboldum!'::text),
(311967,34663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Segítség! ... van a recepció? Én teljesen eltévedtem!'::text,'Hol'::text,'Mi'::text,'Ki'::text,'Segítség! Hol van a recepció? Én teljesen eltévedtem!'::text),
(300558,33396,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Portier ... den alten Mann an der Hoteltür.'::text,'begrüßt'::text,'begrüßen'::text,'begrüßend'::text,'Der Portier begrüßt den alten Mann an der Hoteltür.'::text),
(300562,33396,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Швейцар ... старого чоловіка біля дверей готелю.'::text,'вітає'::text,'вітати'::text,'вітаючи'::text,'Швейцар вітає старого чоловіка біля дверей готелю.'::text),
(300561,33396,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El portero ... al anciano en la puerta del hotel.'::text,'saluda'::text,'saludar'::text,'saludando'::text,'El portero saluda al anciano en la puerta del hotel.'::text),
