(308923,34325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Домашня кішка ... стрибнути на іграшкову мишку.'::text,'може'::text,'може'::text,'може'::text,'Домашня кішка може стрибнути на іграшкову мишку.'::text),
