(308921,34325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat de la maison ... sauter sur la souris en jouet.'::text,'peut'::text,'peut'::text,'peut'::text,'Le chat de la maison peut sauter sur la souris en jouet.'::text),
