(301218,33469,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gente está feliz ... hoy es el Día de la Independencia.'::text,'porque'::text,'pero'::text,'así que'::text,'La gente está feliz porque hoy es el Día de la Independencia.'::text),
