(298677,33187,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, beide Hände an die Seile, Alter. Er ... über das Tal schwingen.'::text,'wird'::text,'wird'::text,'wird'::text,'Yo, beide Hände an die Seile, Alter. Er wird über das Tal schwingen.'::text),
(298681,33187,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, обидві руки на канати, чувак. Він ... над долиною.'::text,'збирається перелетіти'::text,'збирається перелетіти'::text,'збирається перелетіти'::text,'Йо, обидві руки на канати, чувак. Він збирається перелетіти над долиною.'::text),
(298680,33187,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, las dos manos en las cuerdas, tío. Él ... sobre el valle.'::text,'va a columpiarse'::text,'va a columpiarse'::text,'va a columpiarse'::text,'Oye, las dos manos en las cuerdas, tío. Él va a columpiarse sobre el valle.'::text),
(298679,33187,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, les deux mains sur les cordes, mec. Il ... au-dessus de la vallée.'::text,'va se balancer'::text,'va se balancer'::text,'va se balancer'::text,'Yo, les deux mains sur les cordes, mec. Il va se balancer au-dessus de la vallée.'::text),
