(307020,34114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziel: 30 Anrufe. Das Büroteam ... heute noch arbeiten.'::text,'kann'::text,'kann'::text,'kann'::text,'Ziel: 30 Anrufe. Das Büroteam kann heute noch arbeiten.'::text),
