(307092,34122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte öffnet ... auf dem Tisch.'::text,'diesen Koffer'::text,'diese Koffer'::text,'jene Koffer'::text,'Der Beamte öffnet diesen Koffer auf dem Tisch.'::text),
