(307097,34122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur masadaki ... açıyor.'::text,'bu bavulu'::text,'bu bavulu'::text,'şu bavulu'::text,'Memur masadaki bu bavulu açıyor.'::text),
(307098,34122,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt kinyitja ... az asztalon.'::text,'ezt a bőröndöt'::text,'ezeket a bőröndöket'::text,'azokat a bőröndöket'::text,'A tiszt kinyitja ezt a bőröndöt az asztalon.'::text),
(307137,34127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... der Beamte jede Tasche an der Grenze! Ein Albtraum!'::text,'kontrollierte'::text,'kontrolliert'::text,'kontrollieren'::text,'Gestern kontrollierte der Beamte jede Tasche an der Grenze! Ein Albtraum!'::text),
(307141,34127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора офіцер ... кожну сумку на кордоні! Жах!'::text,'перевірив'::text,'перевіряє'::text,'перевіряти'::text,'Учора офіцер перевірив кожну сумку на кордоні! Жах!'::text),
(307140,34127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ayer el agente ... todas las bolsas en la frontera! ¡Una pesadilla!'::text,'revisó'::text,'revisa'::text,'revisar'::text,'¡Ayer el agente revisó todas las bolsas en la frontera! ¡Una pesadilla!'::text),
(307139,34127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, l''agent ... chaque sac à la frontière ! Un cauchemar !'::text,'a contrôlé'::text,'contrôle'::text,'contrôler'::text,'Hier, l''agent a contrôlé chaque sac à la frontière ! Un cauchemar !'::text),
(307142,34127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün memur sınırda her çantayı ...! Kâbus!'::text,'kontrol etti'::text,'kontrol eder'::text,'kontrol etmek'::text,'Dün memur sınırda her çantayı kontrol etti! Kâbus!'::text),
(307143,34127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a tiszt minden táskát ... a határon! Rémálom!'::text,'átvizsgált'::text,'átvizsgál'::text,'átvizsgálni'::text,'Tegnap a tiszt minden táskát átvizsgált a határon! Rémálom!'::text),
(300000,33334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kämpfer stehen in einer Reihe oben auf dem Hügel. Sie ... hinunterrennen.'::text,'werden'::text,'werden'::text,NULL::text,'Kämpfer stehen in einer Reihe oben auf dem Hügel. Sie werden hinunterrennen.'::text),
(300004,33334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бійці стоять у ряд на вершині пагорба. Вони ... вниз.'::text,'збираються збігти'::text,'збіжать'::text,NULL::text,'Бійці стоять у ряд на вершині пагорба. Вони збираються збігти вниз.'::text),
(300003,33334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los guerreros están en fila en lo alto de la colina. Ellos ... cuesta abajo.'::text,'van a correr'::text,'correrán'::text,NULL::text,'Los guerreros están en fila en lo alto de la colina. Ellos van a correr cuesta abajo.'::text),
(300002,33334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des combattants se tiennent en ligne au sommet de la colline. Ils ... la pente.'::text,'vont dévaler'::text,'dévaleront'::text,NULL::text,'Des combattants se tiennent en ligne au sommet de la colline. Ils vont dévaler la pente.'::text),
(300005,33334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Savaşçılar tepenin üstünde sıra halinde duruyor. Onlar aşağı ...'::text,'koşacaklar'::text,'koşacaklar'::text,NULL::text,'Savaşçılar tepenin üstünde sıra halinde duruyor. Onlar aşağı koşacaklar.'::text),
(300006,33334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harcosok állnak sorban a domb tetején. Ők le ... futni.'::text,'fognak'::text,'fognak'::text,NULL::text,'Harcosok állnak sorban a domb tetején. Ők le fognak futni.'::text),
(301449,33495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vorsicht! Er hat ein Bügeleisen, und ... Bügeleisen ist glühend heiß!'::text,'das'::text,'ein'::text,'ein'::text,'Vorsicht! Er hat ein Bügeleisen, und das Bügeleisen ist glühend heiß!'::text),
(301453,33495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обережно! Він має праску, і ... праска розпечена!'::text,''::text,NULL::text,NULL::text,'Обережно! Він має праску, і праска розпечена!'::text),
(301452,33495,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cuidado! Él tiene una plancha, ¡y ... plancha está ardiendo!'::text,'la'::text,'una'::text,'una'::text,'¡Cuidado! Él tiene una plancha, ¡y la plancha está ardiendo!'::text),
(301451,33495,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attention ! Il a un fer à repasser, et ... fer est brûlant !'::text,'le'::text,'un'::text,'un'::text,'Attention ! Il a un fer à repasser, et le fer est brûlant !'::text),
(301454,33495,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat! Onun bir ütüsü var ve ... ütü yanıyor!'::text,''::text,'bir'::text,'bir'::text,'Dikkat! Onun bir ütüsü var ve ütü yanıyor!'::text),
(301455,33495,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vigyázat! Neki van egy vasalója, és ... vasaló tűzforró!'::text,'a'::text,'egy'::text,'egy'::text,'Vigyázat! Neki van egy vasalója, és a vasaló tűzforró!'::text),
(301458,33496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand zwingt mich! Ich ... jedes Hemd für immer mit diesem Bügeleisen bügeln!'::text,'muss'::text,'muss'::text,'sollte'::text,'Niemand zwingt mich! Ich muss jedes Hemd für immer mit diesem Bügeleisen bügeln!'::text),
(301462,33496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто мене не змушує! Я ... прасувати кожну сорочку цією праскою вічно!'::text,'мушу'::text,'маю'::text,'мав би'::text,'Ніхто мене не змушує! Я мушу прасувати кожну сорочку цією праскою вічно!'::text),
(301461,33496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nadie me obliga! ¡Yo ... planchar cada camisa con esta plancha para siempre!'::text,'debo'::text,'tengo que'::text,'debería'::text,'¡Nadie me obliga! ¡Yo debo planchar cada camisa con esta plancha para siempre!'::text),
(301460,33496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne ne m''oblige ! Je ... repasser chaque chemise avec ce fer pour toujours !'::text,'dois'::text,'dois'::text,'devrais'::text,'Personne ne m''oblige ! Je dois repasser chaque chemise avec ce fer pour toujours !'::text),
(301463,33496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse beni zorlamıyor! Ben her gömleği sonsuza dek bu ütüyle ...!'::text,'ütülemeliyim'::text,'ütülemek zorundayım'::text,'ütülemeliyim'::text,'Kimse beni zorlamıyor! Ben her gömleği sonsuza dek bu ütüyle ütülemeliyim!'::text),
(301464,33496,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki sem kényszerít! Nekem minden inget ezzel a vasalóval ... kivasalnom, örökké!'::text,'kell'::text,'kell'::text,'kellene'::text,'Senki sem kényszerít! Nekem minden inget ezzel a vasalóval kell kivasalnom, örökké!'::text),
(328017,36447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stopp! Dieser Holzlöffel ... komplett voller Soße!'::text,'ist'::text,'sind'::text,'bin'::text,'Stopp! Dieser Holzlöffel ist komplett voller Soße!'::text),
(328021,36447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп! Та дерев''яна ложка ... повністю в соусі!'::text,'є'::text,'є'::text,'є'::text,'Стоп! Та дерев''яна ложка є повністю в соусі!'::text),
(328020,36447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para! ¡Esa cuchara de madera ... llenísima de salsa!'::text,'está'::text,'están'::text,'estoy'::text,'¡Para! ¡Esa cuchara de madera está llenísima de salsa!'::text),
(328019,36447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stop ! Cette cuillère en bois ... complètement pleine de sauce !'::text,'est'::text,'sont'::text,'suis'::text,'Stop ! Cette cuillère en bois est complètement pleine de sauce !'::text),
(328022,36447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur! O tahta kaşık tamamen sosla dolu ...!'::text,''::text,NULL::text,NULL::text,'Dur! O tahta kaşık tamamen sosla dolu!'::text),
(328023,36447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állj! Az a fakanál teljesen tele ... szósszal!'::text,'van'::text,'vannak'::text,'vagyok'::text,'Állj! Az a fakanál teljesen tele van szósszal!'::text),
(328035,36449,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich liebt Oma Holzlöffel, aber gestern ... sie eine Gabel.'::text,'benutzte'::text,'benutzt'::text,NULL::text,'Bestie, angeblich liebt Oma Holzlöffel, aber gestern benutzte sie eine Gabel.'::text),
(328039,36449,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, бабуся обожнює дерев''яні ложки, але вчора вона ... виделку.'::text,'використала'::text,'використовує'::text,NULL::text,'Подружко, кажуть, бабуся обожнює дерев''яні ложки, але вчора вона використала виделку.'::text),
(328038,36449,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que la abuela adora las cucharas de madera, pero ayer ella ... un tenedor.'::text,'usó'::text,'usa'::text,NULL::text,'Amiga, parece que la abuela adora las cucharas de madera, pero ayer ella usó un tenedor.'::text),
(328037,36449,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment mamie adore les cuillères en bois, mais hier elle ... une fourchette.'::text,'a utilisé'::text,'utilise'::text,NULL::text,'Ma belle, apparemment mamie adore les cuillères en bois, mais hier elle a utilisé une fourchette.'::text),
(328040,36449,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre babaanne tahta kaşıklara bayılıyormuş ama dün o bir çatal ...'::text,'kullandı'::text,'kullanır'::text,NULL::text,'Kanka, duyduğuma göre babaanne tahta kaşıklara bayılıyormuş ama dün o bir çatal kullandı.'::text),
(328041,36449,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a nagyi imádja a fakanalakat, de tegnap ő egy villát ...'::text,'használt'::text,'használ'::text,NULL::text,'Csajszi, állítólag a nagyi imádja a fakanalakat, de tegnap ő egy villát használt.'::text),
(322752,35862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fischscheiben ... sehr dünn.'::text,'sind'::text,'ist'::text,'bin'::text,'Die Fischscheiben sind sehr dünn.'::text),
(322756,35862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скибочки риби ... дуже тонкі.'::text,'є'::text,'є'::text,'є'::text,'Скибочки риби є дуже тонкі.'::text),
(322755,35862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las lonchas de pescado ... muy finas.'::text,'son'::text,'es'::text,'soy'::text,'Las lonchas de pescado son muy finas.'::text),
(322754,35862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les tranches de poisson ... très fines.'::text,'sont'::text,'est'::text,'suis'::text,'Les tranches de poisson sont très fines.'::text),
(322757,35862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balık dilimleri çok ince ...'::text,''::text,NULL::text,NULL::text,'Balık dilimleri çok ince.'::text),
(322758,35862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A halszeletek ... nagyon vékonyak.'::text,''::text,NULL::text,'vagyok'::text,'A halszeletek nagyon vékonyak.'::text),
(322779,35865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr großzügig, klar: Diese Scheibe ist ... als Papier.'::text,'dünner'::text,'dünner'::text,'am dünnsten'::text,'Sehr großzügig, klar: Diese Scheibe ist dünner als Papier.'::text),
(322783,35865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже щедро, звісно: ця скибочка ... за папір.'::text,'тонша'::text,'більш тонка'::text,'найтонша'::text,'Дуже щедро, звісно: ця скибочка тонша за папір.'::text),
(322782,35865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy generoso, obvio: esta loncha es ... que el papel.'::text,'más fina'::text,'más fina'::text,'la más fina'::text,'Muy generoso, obvio: esta loncha es más fina que el papel.'::text),
(322781,35865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très généreux, évidemment : cette tranche est ... que du papier.'::text,'plus fine'::text,'plus fine'::text,'la plus fine'::text,'Très généreux, évidemment : cette tranche est plus fine que du papier.'::text),
(322784,35865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok cömert, tabii: bu dilim kâğıttan ...'::text,'daha ince'::text,'daha ince'::text,'en ince'::text,'Çok cömert, tabii: bu dilim kâğıttan daha ince.'::text),
(322785,35865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon nagyvonalú, persze: ez a szelet ..., mint a papír.'::text,'vékonyabb'::text,'vékonyabb'::text,'legvékonyabb'::text,'Nagyon nagyvonalú, persze: ez a szelet vékonyabb, mint a papír.'::text),
(302808,33646,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie erreicht den Grat ... Nachmittag und sieht die Landschaft.'::text,'am'::text,'am'::text,'um den'::text,'Sie erreicht den Grat am Nachmittag und sieht die Landschaft.'::text),
(302812,33646,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона дістається хребта ... другій половині дня і бачить краєвид.'::text,'у'::text,'на'::text,'о'::text,'Вона дістається хребта у другій половині дня і бачить краєвид.'::text),
(302811,33646,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella llega a la cresta ... la tarde y ve el paisaje.'::text,'por'::text,'en'::text,'a'::text,'Ella llega a la cresta por la tarde y ve el paisaje.'::text),
(302810,33646,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle atteint la crête ... l''après-midi et voit le paysage.'::text,'dans'::text,'sur'::text,'à'::text,'Elle atteint la crête dans l''après-midi et voit le paysage.'::text),
(302813,33646,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O öğleden sonra ... sırta varıyor ve manzarayı görüyor.'::text,''::text,NULL::text,NULL::text,'O öğleden sonra sırta varıyor ve manzarayı görüyor.'::text),
(302814,33646,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... ér fel a gerincre, és meglátja a tájat.'::text,'délután'::text,'délutánon'::text,'délutánkor'::text,'Ő délután ér fel a gerincre, és meglátja a tájat.'::text),
(302826,33648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... sie für diese Landschaft den schlimmsten Weg aller Zeiten hinauf!'::text,'kletterte'::text,'klettert'::text,'klettern'::text,'Gestern kletterte sie für diese Landschaft den schlimmsten Weg aller Zeiten hinauf!'::text),
(302830,33648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора вона ... найгіршою стежкою в історії заради цього краєвиду!'::text,'видерлася'::text,'дереться'::text,'дертися'::text,'Учора вона видерлася найгіршою стежкою в історії заради цього краєвиду!'::text),
(302829,33648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ayer ella ... el peor camino de la historia por este paisaje!'::text,'subió'::text,'sube'::text,'subir'::text,'¡Ayer ella subió el peor camino de la historia por este paisaje!'::text),
(302828,33648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, elle ... le pire chemin de tous les temps pour ce paysage !'::text,'a grimpé'::text,'grimpe'::text,'grimper'::text,'Hier, elle a grimpé le pire chemin de tous les temps pour ce paysage !'::text),
(302831,33648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün o bu manzara için gelmiş geçmiş en kötü patikaya ...!'::text,'tırmandı'::text,'tırmanır'::text,'tırmanmak'::text,'Dün o bu manzara için gelmiş geçmiş en kötü patikaya tırmandı!'::text),
(302832,33648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ő minden idők legrosszabb ösvényén ... fel ezért a tájért!'::text,'mászott'::text,'mászik'::text,'mászni'::text,'Tegnap ő minden idők legrosszabb ösvényén mászott fel ezért a tájért!'::text),
(318882,35432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Känguru stößt sich vom Sand ab. Es ... nach vorn springen.'::text,'wird'::text,'wird'::text,NULL::text,'Das Känguru stößt sich vom Sand ab. Es wird nach vorn springen.'::text),
(318886,35432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кенгуру відштовхується від піску. Воно ... стрибнути вперед.'::text,'збирається'::text,'буде'::text,NULL::text,'Кенгуру відштовхується від піску. Воно збирається стрибнути вперед.'::text),
(318885,35432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El canguro se impulsa en la arena. Él ... saltar hacia delante.'::text,'va a'::text,NULL::text,NULL::text,'El canguro se impulsa en la arena. Él va a saltar hacia delante.'::text),
(318884,35432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le kangourou prend appui sur le sable. Il ... bondir en avant.'::text,'va'::text,NULL::text,NULL::text,'Le kangourou prend appui sur le sable. Il va bondir en avant.'::text),
(318887,35432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanguru kumdan güç alıyor. O ileri ...'::text,'sıçrayacak'::text,'sıçrayacak'::text,NULL::text,'Kanguru kumdan güç alıyor. O ileri sıçrayacak.'::text),
(318888,35432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kenguru elrugaszkodik a homoktól. Ő előre ... ugrani.'::text,'fog'::text,'fog'::text,NULL::text,'A kenguru elrugaszkodik a homoktól. Ő előre fog ugrani.'::text),
(301917,33547,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, ich ... mir so einen Wasserkocher wie ihren holen, bin lowkey besessen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Nee, ich muss mir so einen Wasserkocher wie ihren holen, bin lowkey besessen.'::text),
(301921,33547,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, я ... дістати такий чайник, як у неї, трохи одержима.'::text,'мушу'::text,'маю'::text,'мала б'::text,'Не, я мушу дістати такий чайник, як у неї, трохи одержима.'::text),
(301920,33547,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No, yo ... conseguir un hervidor como el suyo, estoy un poco obsesionada.'::text,'debo'::text,'tengo que'::text,'debería'::text,'No, yo debo conseguir un hervidor como el suyo, estoy un poco obsesionada.'::text),
(301919,33547,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, je ... trouver une bouilloire comme la sienne, je suis un peu obsédée.'::text,'dois'::text,'dois'::text,'devrais'::text,'Non, je dois trouver une bouilloire comme la sienne, je suis un peu obsédée.'::text),
(301922,33547,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, ben de onunki gibi bir su ısıtıcısı ..., resmen takıntı oldu.'::text,'almalıyım'::text,'almak zorundayım'::text,'almalıyım'::text,'Yok, ben de onunki gibi bir su ısıtıcısı almalıyım, resmen takıntı oldu.'::text),
(301923,33547,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, nekem ... szereznem egy ilyen vízforralót, mint az övé, kicsit rá vagyok kattanva.'::text,'kell'::text,'kell'::text,'kellene'::text,'Nem, nekem kell szereznem egy ilyen vízforralót, mint az övé, kicsit rá vagyok kattanva.'::text),
(304140,33794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Schlüssel im Schloss.'::text,'dreht'::text,'drehen'::text,'drehend'::text,'Sie dreht den Schlüssel im Schloss.'::text),
(304144,33794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... ключ у замку.'::text,'повертає'::text,'повертати'::text,'повертаючи'::text,'Вона повертає ключ у замку.'::text),
(304143,33794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la llave en la cerradura.'::text,'gira'::text,'girar'::text,'girando'::text,'Ella gira la llave en la cerradura.'::text),
(304142,33794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la clé dans la serrure.'::text,'tourne'::text,'tourner'::text,'tournant'::text,'Elle tourne la clé dans la serrure.'::text),
(304145,33794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O anahtarı kilitte ...'::text,'çevirir'::text,'çevirmek'::text,'çevirerek'::text,'O anahtarı kilitte çevirir.'::text),
(304146,33794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a kulcsot a zárban.'::text,'elfordítja'::text,'elfordítani'::text,'elfordító'::text,'Ő elfordítja a kulcsot a zárban.'::text),
(304194,33800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schlüssel öffnet das Schloss, ... er ein Schlüssel für dieses Schloss ist.'::text,'weil'::text,'aber'::text,'also'::text,'Der Schlüssel öffnet das Schloss, weil er ein Schlüssel für dieses Schloss ist.'::text),
(304198,33800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ключ відчиняє замок, ... це ключ від того замка.'::text,'бо'::text,'але'::text,'тому'::text,'Ключ відчиняє замок, бо це ключ від того замка.'::text),
(304197,33800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La llave abre la cerradura ... es una llave de esa cerradura.'::text,'porque'::text,'pero'::text,'así que'::text,'La llave abre la cerradura porque es una llave de esa cerradura.'::text),
(304196,33800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La clé ouvre la serrure ... c''est une clé pour cette serrure.'::text,'parce que'::text,'mais'::text,'donc'::text,'La clé ouvre la serrure parce que c''est une clé pour cette serrure.'::text),
(304199,33800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anahtar kilidi açıyor ... bu, o kilidin anahtarı.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Anahtar kilidi açıyor çünkü bu, o kilidin anahtarı.'::text),
(304200,33800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kulcs kinyitja a zárat, ... ez annak a zárnak a kulcsa.'::text,'mert'::text,'de'::text,'ezért'::text,'A kulcs kinyitja a zárat, mert ez annak a zárnak a kulcsa.'::text),
(302142,33572,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist der König? Er ist der Mann mit der Krone.'::text,'Wer'::text,'Was'::text,'Wo'::text,'Wer ist der König? Er ist der Mann mit der Krone.'::text),
(302146,33572,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... король? Він — чоловік із короною.'::text,'Хто'::text,'Що'::text,'Де'::text,'Хто король? Він — чоловік із короною.'::text),
(302145,33572,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... es el rey? Él es el hombre de la corona.'::text,'Quién'::text,'Qué'::text,'Dónde'::text,'¿Quién es el rey? Él es el hombre de la corona.'::text),
(302144,33572,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est le roi ? C''est l''homme avec la couronne.'::text,'Qui'::text,'Quoi'::text,'Où'::text,'Qui est le roi ? C''est l''homme avec la couronne.'::text),
(302147,33572,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kral ...? O, taçlı adam.'::text,'kim'::text,'ne'::text,'nerede'::text,'Kral kim? O, taçlı adam.'::text),
(302148,33572,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a király? Ő a koronás férfi.'::text,'Ki'::text,'Mi'::text,'Hol'::text,'Ki a király? Ő a koronás férfi.'::text),
(302169,33575,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... der König seine Krone! Der absolut beste Tag!'::text,'bekam'::text,'bekommt'::text,'bekommen'::text,'Gestern bekam der König seine Krone! Der absolut beste Tag!'::text),
(302173,33575,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора король ... свою корону! Найкращий день!'::text,'отримав'::text,'отримує'::text,'отримувати'::text,'Учора король отримав свою корону! Найкращий день!'::text),
(302172,33575,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ayer el rey ... su corona! ¡El mejor día de todos!'::text,'recibió'::text,'recibe'::text,'recibir'::text,'¡Ayer el rey recibió su corona! ¡El mejor día de todos!'::text),
(302171,33575,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, le roi ... sa couronne ! Le meilleur jour de tous !'::text,'a reçu'::text,'reçoit'::text,'recevoir'::text,'Hier, le roi a reçu sa couronne ! Le meilleur jour de tous !'::text),
(302174,33575,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün kral tacını ...! Gelmiş geçmiş en güzel gün!'::text,'aldı'::text,'alır'::text,'almak'::text,'Dün kral tacını aldı! Gelmiş geçmiş en güzel gün!'::text),
(302175,33575,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a király ... a koronáját! Minden idők legjobb napja!'::text,'megkapta'::text,'megkapja'::text,'megkapni'::text,'Tegnap a király megkapta a koronáját! Minden idők legjobb napja!'::text),
(307164,34130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... alt, und sie küssen sich ewig! Einfach wunderschön!'::text,'sind'::text,'ist'::text,'bin'::text,'Sie sind alt, und sie küssen sich ewig! Einfach wunderschön!'::text),
(307168,34130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... старі, і вони цілуються вічність! Просто прекрасно!'::text,'є'::text,'є'::text,'є'::text,'Вони є старі, і вони цілуються вічність! Просто прекрасно!'::text),
(307167,34130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... mayores y se besan eternamente! ¡Absolutamente precioso!'::text,'son'::text,'es'::text,'soy'::text,'¡Ellos son mayores y se besan eternamente! ¡Absolutamente precioso!'::text),
(307166,34130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... vieux, et ils s''embrassent une éternité ! Absolument magnifique !'::text,'sont'::text,'est'::text,'suis'::text,'Ils sont vieux, et ils s''embrassent une éternité ! Absolument magnifique !'::text),
(307169,34130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar yaşlı ... ve sonsuza dek öpüşüyorlar! Resmen çok güzel!'::text,''::text,NULL::text,NULL::text,'Onlar yaşlı ve sonsuza dek öpüşüyorlar! Resmen çok güzel!'::text),
(307170,34130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők ... idősek, és örökké csókolóznak! Egyszerűen gyönyörű!'::text,''::text,NULL::text,'vagyok'::text,'Ők idősek, és örökké csókolóznak! Egyszerűen gyönyörű!'::text),
(307218,34136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ist ein langer Spaziergang, also ... das alte Paar sich auf die Bank setzen.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Es ist ein langer Spaziergang, also sollte das alte Paar sich auf die Bank setzen.'::text),
(307222,34136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це довга прогулянка, тож стара пара ... посидіти на лавці.'::text,'мала б'::text,'мала б'::text,'буде'::text,'Це довга прогулянка, тож стара пара мала б посидіти на лавці.'::text),
(307221,34136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es un paseo largo, así que la pareja mayor ... sentarse en el banco.'::text,'debería'::text,'debería'::text,'deberá'::text,'Es un paseo largo, así que la pareja mayor debería sentarse en el banco.'::text),
(307220,34136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est une longue promenade, alors le vieux couple ... s''asseoir sur le banc.'::text,'devrait'::text,'devrait'::text,'devra'::text,'C''est une longue promenade, alors le vieux couple devrait s''asseoir sur le banc.'::text),
(307223,34136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun bir yürüyüş, bu yüzden yaşlı çift bankta ...'::text,'oturmalı'::text,'oturmalı'::text,'oturacak'::text,'Uzun bir yürüyüş, bu yüzden yaşlı çift bankta oturmalı.'::text),
(307224,34136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hosszú a séta, ezért az idős párnak le ... ülnie a padra.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Hosszú a séta, ezért az idős párnak le kellene ülnie a padra.'::text),
(313563,34841,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Romantik ... das alte Paar im Café sehr glücklich.'::text,'macht'::text,'machen'::text,'machend'::text,'Romantik macht das alte Paar im Café sehr glücklich.'::text),
(313567,34841,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Романтика ... літню пару в кафе дуже щасливою.'::text,'робить'::text,'робити'::text,'роблячи'::text,'Романтика робить літню пару в кафе дуже щасливою.'::text),
(313566,34841,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El romance ... muy feliz a la pareja mayor del café.'::text,'hace'::text,'hacer'::text,'haciendo'::text,'El romance hace muy feliz a la pareja mayor del café.'::text),
(313565,34841,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La romance ... le vieux couple du café très heureux.'::text,'rend'::text,'rendre'::text,'rendant'::text,'La romance rend le vieux couple du café très heureux.'::text),
(313568,34841,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşk kafedeki yaşlı çifti çok mutlu ...'::text,'eder'::text,'etmek'::text,'ederek'::text,'Aşk kafedeki yaşlı çifti çok mutlu eder.'::text),
(313569,34841,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A romantika nagyon boldoggá ... az idős párt a kávézóban.'::text,'teszi'::text,'tenni'::text,'tevő'::text,'A romantika nagyon boldoggá teszi az idős párt a kávézóban.'::text),
(313608,34846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zu ... Romantik auf einer Straße! Ich kann absolut nicht atmen!'::text,'viel'::text,'viele'::text,'irgendwelche'::text,'Zu viel Romantik auf einer Straße! Ich kann absolut nicht atmen!'::text),
(313612,34846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Надто ... романтики на одній вулиці! Я зовсім не можу дихати!'::text,'багато'::text,'багато'::text,'якоїсь'::text,'Надто багато романтики на одній вулиці! Я зовсім не можу дихати!'::text),
(313611,34846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hay ... romance en una sola calle! ¡Yo no puedo respirar para nada!'::text,'demasiado'::text,'demasiados'::text,'algún'::text,'¡Hay demasiado romance en una sola calle! ¡Yo no puedo respirar para nada!'::text),
(313610,34846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a ... romance dans une seule rue ! Je n''arrive absolument pas à respirer !'::text,'trop de'::text,'trop de'::text,'aucune'::text,'Il y a trop de romance dans une seule rue ! Je n''arrive absolument pas à respirer !'::text),
(313613,34846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir sokakta ... fazla aşk! Ben kesinlikle nefes alamıyorum!'::text,'çok'::text,'çok'::text,'herhangi'::text,'Tek bir sokakta çok fazla aşk! Ben kesinlikle nefes alamıyorum!'::text),
(313614,34846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Túl ... romantika egyetlen utcán! Én egyáltalán nem kapok levegőt!'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Túl sok romantika egyetlen utcán! Én egyáltalán nem kapok levegőt!'::text),
(313077,34787,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kochst du so? Reiche Küche, smoothe Moves.'::text,'Wie'::text,'Wer'::text,'Wo'::text,'Wie kochst du so? Reiche Küche, smoothe Moves.'::text),
(313081,34787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ти так готуєш? Багата кухня, круті рухи.'::text,'Як'::text,'Хто'::text,'Де'::text,'Як ти так готуєш? Багата кухня, круті рухи.'::text),
(313080,34787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... cocinas tú así? Cocina de rico, movimientos finos.'::text,'Cómo'::text,'Quién'::text,'Dónde'::text,'¿Cómo cocinas tú así? Cocina de rico, movimientos finos.'::text),
(313079,34787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tu cuisines comme ça ? Cuisine de riche, gestes fluides.'::text,'Comment'::text,'Qui'::text,'Où'::text,'Comment tu cuisines comme ça ? Cuisine de riche, gestes fluides.'::text),
(313082,34787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen ... böyle yemek yapıyorsun? Zengin mutfağı, akıcı hareketler.'::text,'nasıl'::text,'kim'::text,'nerede'::text,'Sen nasıl böyle yemek yapıyorsun? Zengin mutfağı, akıcı hareketler.'::text),
(313083,34787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... főzöl te így? Gazdag konyha, laza mozdulatok.'::text,'Hogyan'::text,'Ki'::text,'Hol'::text,'Hogyan főzöl te így? Gazdag konyha, laza mozdulatok.'::text),
(313113,34791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, angeblich kocht dieser reiche Typ nie, aber jetzt ... er Paprika.'::text,'brät'::text,'brät'::text,NULL::text,'Rate mal, angeblich kocht dieser reiche Typ nie, aber jetzt brät er Paprika.'::text),
(313117,34791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, той багатий хлопець ніколи не готує, а зараз він ... перці.'::text,'смажить'::text,'смажить'::text,NULL::text,'Уяви, кажуть, той багатий хлопець ніколи не готує, а зараз він смажить перці.'::text),
(313116,34791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, parece que ese tío rico nunca cocina, pero ahora él ... pimientos.'::text,'está friendo'::text,'fríe'::text,NULL::text,'Adivina, parece que ese tío rico nunca cocina, pero ahora él está friendo pimientos.'::text),
(313115,34791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment ce mec riche ne cuisine jamais, mais là, il ... des poivrons.'::text,'est en train de faire frire'::text,'fait frire'::text,NULL::text,'Devine quoi, apparemment ce mec riche ne cuisine jamais, mais là, il est en train de faire frire des poivrons.'::text),
(313118,34791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et, o zengin adam hiç yemek yapmazmış ama şimdi o biber ...'::text,'kızartıyor'::text,'kızartır'::text,NULL::text,'Tahmin et, o zengin adam hiç yemek yapmazmış ama şimdi o biber kızartıyor.'::text),
(313119,34791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag az a gazdag srác sosem főz, de most ő paprikát ...'::text,'süt'::text,'süt'::text,NULL::text,'Képzeld, állítólag az a gazdag srác sosem főz, de most ő paprikát süt.'::text),
(302547,33617,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Knie und geht in die Hocke.'::text,'beugt'::text,'beugen'::text,'beugend'::text,'Er beugt die Knie und geht in die Hocke.'::text),
(302551,33617,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... коліна й опускається в присід.'::text,'згинає'::text,'згинати'::text,'згинаючи'::text,'Він згинає коліна й опускається в присід.'::text),
(302550,33617,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... las rodillas y baja en sentadilla.'::text,'dobla'::text,'doblar'::text,'doblando'::text,'Él dobla las rodillas y baja en sentadilla.'::text),
