(302553,33617,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a térdét, és guggolásba ereszkedik.'::text,'behajlítja'::text,'behajlítani'::text,'behajlító'::text,'Ő behajlítja a térdét, és guggolásba ereszkedik.'::text),
(302601,33623,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Patient. Sein Knie tat weh, ... jetzt macht er Kniebeugen wie ein Profi.'::text,'aber'::text,'also'::text,'weil'::text,'Toller Patient. Sein Knie tat weh, aber jetzt macht er Kniebeugen wie ein Profi.'::text),
(302605,33623,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий пацієнт. Коліно в нього боліло, ... тепер він присідає як профі.'::text,'але'::text,'тому'::text,'бо'::text,'Чудовий пацієнт. Коліно в нього боліло, але тепер він присідає як профі.'::text),
(302604,33623,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran paciente. Le dolía la rodilla, ... ahora él hace sentadillas como un pro.'::text,'pero'::text,'así que'::text,'porque'::text,'Gran paciente. Le dolía la rodilla, pero ahora él hace sentadillas como un pro.'::text),
(302603,33623,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super patient. Il avait mal au genou, ... maintenant il fait des squats comme un pro.'::text,'mais'::text,'donc'::text,'parce que'::text,'Super patient. Il avait mal au genou, mais maintenant il fait des squats comme un pro.'::text),
