(312663,34741,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie ... die kaputte Birne selbst aus, ziemlich cool.'::text,'tauscht'::text,'tauschen'::text,'tauschend'::text,'Alter, sie tauscht die kaputte Birne selbst aus, ziemlich cool.'::text),
(312667,34741,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона сама ... перегорілу лампочку, досить круто.'::text,'міняє'::text,'міняти'::text,'міняючи'::text,'Чувак, вона сама міняє перегорілу лампочку, досить круто.'::text),
(312666,34741,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... la bombilla fundida sola, bastante guay.'::text,'cambia'::text,'cambiar'::text,'cambiando'::text,'Tío, ella cambia la bombilla fundida sola, bastante guay.'::text),
(312665,34741,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle ... l''ampoule grillée toute seule, plutôt cool.'::text,'remplace'::text,'remplacer'::text,'remplaçant'::text,'Mec, elle remplace l''ampoule grillée toute seule, plutôt cool.'::text),
(312668,34741,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yanık ampulü kendisi ..., baya havalı.'::text,'değiştirir'::text,'değiştirmek'::text,'değiştirerek'::text,'Kanka, o yanık ampulü kendisi değiştirir, baya havalı.'::text),
