(312708,34746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Zimmer ist dunkel, also ... sie heute die Birne wechseln.'::text,'muss'::text,'muss'::text,'sollte'::text,'Das Zimmer ist dunkel, also muss sie heute die Birne wechseln.'::text),
(312712,34746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У кімнаті темно, тож вона ... сьогодні замінити лампочку.'::text,'має'::text,'мусить'::text,'мала б'::text,'У кімнаті темно, тож вона має сьогодні замінити лампочку.'::text),
