(312713,34746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oda karanlık, bu yüzden o bugün ampulü ...'::text,'değiştirmek zorunda'::text,'değiştirmeli'::text,'değiştirmeli'::text,'Oda karanlık, bu yüzden o bugün ampulü değiştirmek zorunda.'::text),
