(302669,33630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hanımefendinin masada ... demliği var.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Hanımefendinin masada bir demliği var.'::text),
