(302673,33631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, gestern ... die Dame allen Tee ein, hat voll abgeliefert.'::text,'schenkte'::text,'schenkt'::text,'schenken'::text,'Alter, gestern schenkte die Dame allen Tee ein, hat voll abgeliefert.'::text),
