(302676,33631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ayer la dama ... té para todos, lo petó.'::text,'sirvió'::text,'sirve'::text,'servir'::text,'Tío, ayer la dama sirvió té para todos, lo petó.'::text),
(302675,33631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, hier la dame ... du thé à tout le monde, elle a géré.'::text,'a versé'::text,'verse'::text,'verser'::text,'Mec, hier la dame a versé du thé à tout le monde, elle a géré.'::text),
(302678,33631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dün hanımefendi herkese çay ..., resmen döktürdü.'::text,'doldurdu'::text,'doldurur'::text,'doldurmak'::text,'Kanka, dün hanımefendi herkese çay doldurdu, resmen döktürdü.'::text),
