(303206,33690,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les alpinistes le suivent ... c''est leur chef.'::text,'parce que'::text,'mais'::text,'donc'::text,'Les alpinistes le suivent parce que c''est leur chef.'::text),
