(303210,33690,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hegymászók követik őt, ... ő a vezetőjük.'::text,'mert'::text,'de'::text,'ezért'::text,'A hegymászók követik őt, mert ő a vezetőjük.'::text),
(321708,35746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie jonglieren gleich ... mit purem Talent.'::text,'3 Bälle'::text,'3 Ball'::text,'3 Bälle'::text,'Alter, sie jonglieren gleich 3 Bälle mit purem Talent.'::text),
(321712,35746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони жонглюватимуть ... на чистому таланті.'::text,'3 м''ячами'::text,'3 м''ячем'::text,'3 м''ячами'::text,'Бро, вони жонглюватимуть 3 м''ячами на чистому таланті.'::text),
(321711,35746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ellos van a hacer malabares con ..., a puro talento.'::text,'3 pelotas'::text,'3 pelota'::text,'3 pelotas'::text,'Tío, ellos van a hacer malabares con 3 pelotas, a puro talento.'::text),
(321710,35746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ils vont jongler avec ... grâce à leur pur talent.'::text,'3 balles'::text,'3 balle'::text,'3 balles'::text,'Mec, ils vont jongler avec 3 balles grâce à leur pur talent.'::text),
(321713,35746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onlar saf yetenekle ... jonglörlük yapacak.'::text,'3 topla'::text,'3 topla'::text,'3 toplarla'::text,'Kanka, onlar saf yetenekle 3 topla jonglörlük yapacak.'::text),
