(321762,35752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jonglieren braucht Talent und jeden Tag viel ...'::text,'Geduld'::text,'Geduld'::text,'eine Geduld'::text,'Jonglieren braucht Talent und jeden Tag viel Geduld.'::text),
(321766,35752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жонглювання потребує таланту і багато ... щодня.'::text,'терпіння'::text,'терпіння'::text,'терпіння'::text,'Жонглювання потребує таланту і багато терпіння щодня.'::text),
(321765,35752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hacer malabares requiere talento y mucha ... cada día.'::text,'paciencia'::text,'paciencia'::text,'una paciencia'::text,'Hacer malabares requiere talento y mucha paciencia cada día.'::text),
