(321767,35752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jonglörlük her gün yetenek ve çok ... ister.'::text,'sabır'::text,'sabırlar'::text,'bir sabır'::text,'Jonglörlük her gün yetenek ve çok sabır ister.'::text),
